let REDUCE_MOTION = false;

function prefersReducedMotion() {
  try { return !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches); } catch (e) { return false; }
}
function loadA11y() {
  try {
    const raw = window.localStorage.getItem(A11Y_KEY);
    if (raw) return { ...A11Y_DEFAULT, ...JSON.parse(raw) };
  } catch (e) {}
  return { ...A11Y_DEFAULT };
}
function saveA11y(st) {
  try { window.localStorage.setItem(A11Y_KEY, JSON.stringify(st)); } catch (e) {}
}
function setVLibras(on) {
  let box = document.getElementById("sigep-vlibras");
  if (on) {
    if (!box) {
      box = document.createElement("div");
      box.id = "sigep-vlibras";
      box.innerHTML = '<div vw class="enabled"><div vw-access-button class="active"></div><div vw-plugin-wrapper><div class="vw-plugin-top-wrapper"></div></div></div>';
      document.body.appendChild(box);
      const sc = document.createElement("script");
      sc.src = "https://vlibras.gov.br/app/vlibras-plugin.js";
      sc.onload = () => { try { new window.VLibras.Widget("https://vlibras.gov.br/app"); } catch (e) {} };
      document.body.appendChild(sc);
    } else {
      box.style.display = "";
    }
  } else if (box) {
    box.style.display = "none";
  }
}
function applyA11y(st) {
  const h = document.documentElement;
  h.style.removeProperty("font-size");
  h.style.setProperty("--a11y-scale", String(st.fontScale / 100));
  h.classList.toggle("a11y-font-atkinson", st.font === "atkinson");
  h.classList.toggle("a11y-font-opendyslexic", st.font === "opendyslexic");
  h.classList.toggle("a11y-letter", st.letter > 0);
  h.style.setProperty("--a11y-ls", st.letter > 0 ? (st.letter * 0.02).toFixed(2) + "em" : "normal");
  h.classList.toggle("a11y-line", st.line > 0);
  h.style.setProperty("--a11y-lh", st.line > 0 ? (1.1 + 0.1 * st.line).toFixed(1) : "normal");
  h.classList.toggle("a11y-targets", !!st.targets);
  h.classList.toggle("a11y-motion-reduce", st.motion === "reduce");
  h.classList.toggle("a11y-motion-full", st.motion === "full");
  setVLibras(!!st.vlibras);
}


