function buildSeed() {
  const instituicao = {
    nome: "Etec de Heliópolis – Arquiteto Ruy Ohtake",
    cnpj: "62.823.257/0223-45",
    endereco: "Av. República do Líbano, s/n - Heliópolis, São Paulo - SP",
    telefone: "(11) 2892-4200",
    email: "e223@cps.sp.gov.br",
  };

  const responsaveis = NOMES_RESP.map((nome, i) => ({
    id: `R${String(i + 1).padStart(3, "0")}`,
    nome,
    cpf: maskCPF(String(10000000000 + i * 987654321).slice(0, 11)),
    email: `${nome.toLowerCase().split(" ")[0]}.${nome.toLowerCase().split(" ").pop()}@email.com`,
    telefone: maskPhone(`11 9${8000 + i}${1000 + i}`),
    senha: "123456",
    status: "Ativo",
  }));
  // demo account overrides first responsavel
  responsaveis[0] = { ...responsaveis[0], id: "R001", nome: "Marcos Souza", email: "responsavel@sigep.com", senha: "123456", status: "Ativo" };

  const orientadores = NOMES_ORIENT.map((nome, i) => ({
    id: `O${String(i + 1).padStart(3, "0")}`,
    nome,
    cpf: maskCPF(String(20000000000 + i * 123456789).slice(0, 11)),
    email: `${nome.split(" ").pop().toLowerCase()}@sigep.com`,
    telefone: maskPhone(`11 9${7000 + i}${2000 + i}`),
    senha: "123456",
    instituicao: instituicao.nome,
    status: "Ativo",
  }));
  orientadores[0] = { ...orientadores[0], id: "O001", nome: "Prof. Marcelo Antunes", email: "orientador@sigep.com", senha: "123456", status: "Ativo" };

  const alunos = NOMES_ALUNOS.map((nome, i) => ({
    rm: `${20250000 + i}`,
    nome,
    ano: ANOS[i % ANOS.length],
    curso: CURSOS[i % CURSOS.length],
    periodo: PERIODOS[i % PERIODOS.length],
    responsavelId: responsaveis[i % responsaveis.length].id,
    status: i % 9 === 0 ? "Inativo" : "Ativo",
  }));

  const STATUS_LIST = ["Pendente", "Confirmado", "Finalizado", "Cancelado", "Em Andamento"];
  const atendimentos = [];
  for (let i = 0; i < 100; i++) {
    const aluno = alunos[i % alunos.length];
    const orientador = orientadores[i < 20 ? 0 : i % orientadores.length];
    const offset = i - 14; // spread across past/future
    const data = addDays(TODAY, offset);
    const hora = `${8 + (i % 8)}:${i % 2 === 0 ? "00" : "30"}`;
    let status = STATUS_LIST[i % STATUS_LIST.length];
    if (offset < -1 && status === "Confirmado") status = "Finalizado";
    if (offset < -1 && status === "Pendente") status = "Cancelado";
    atendimentos.push({
      id: `A${String(i + 1).padStart(4, "0")}`,
      alunoRm: aluno.rm,
      orientadorId: orientador.id,
      responsavelId: aluno.responsavelId,
      data: dateKey(data),
      horario: hora,
      motivo: MOTIVOS[i % MOTIVOS.length],
      descricao: "",
      observacoes: "",
      resultado: status === "Finalizado" ? "Aluno orientado com sucesso; encaminhado plano de ação para as próximas semanas." : "",
      status,
      criadoEm: dateKey(addDays(data, -3)),
    });
  }

  const notificacoes = [
    { id: uid("N"), responsavelId: "R001", texto: "Seu atendimento foi confirmado.", lida: false, data: dateKey(addDays(TODAY, -1)) },
    { id: uid("N"), responsavelId: "R001", texto: "Seu atendimento está agendado para amanhã.", lida: false, data: dateKey(TODAY) },
    { id: uid("N"), responsavelId: "R001", texto: "Seu atendimento foi alterado.", lida: true, data: dateKey(addDays(TODAY, -3)) },
    { id: uid("N"), responsavelId: "R001", texto: "Seu atendimento foi cancelado.", lida: true, data: dateKey(addDays(TODAY, -6)) },
  ];

  // Vínculos N:N entre alunos e responsáveis — equivale à tabela intermediária "responsavel_aluno" (alunoRm ⇄ responsavelId).
  // Um aluno pode ter 2 ou mais responsáveis e um responsável pode ter vários alunos. Perfis continuam todos em "usuários".
  const responsavelAluno = alunos.map((a) => ({ alunoRm: a.rm, responsavelId: a.responsavelId }));
  [[1, 2], [3, 0], [8, 4]].forEach(([ai, ri]) => { // alguns alunos de exemplo com 2 responsáveis
    const rid = responsaveis[ri].id;
    if (!responsavelAluno.some((v) => v.alunoRm === alunos[ai].rm && v.responsavelId === rid)) responsavelAluno.push({ alunoRm: alunos[ai].rm, responsavelId: rid });
  });
  const alunosSemResp = alunos.map(({ responsavelId, ...resto }) => resto);
  return { instituicao, responsaveis, orientadores, alunos: alunosSemResp, atendimentos, notificacoes, responsavelAluno };
}

