/* ============================================================
   TOASTS
   ============================================================ */
function ToastStack({ toasts, remove }) {
  return (
    <div className="fixed top-4 right-4 z-[100] flex flex-col gap-2 w-80">
      {toasts.map((t) => (
        <div
          key={t.id}
          className={`flex items-start gap-2 px-4 py-3 rounded-lg shadow-lg border text-sm bg-white animate-[fadeIn_.2s_ease-out] ${
            t.type === "success" ? "border-[#A0C340]/50" : t.type === "error" ? "border-[#FF4C4D]/30" : "border-[#4C7EFF]/30"
          }`}
        >
          {t.type === "success" && <CheckCircle2 size={18} className="text-[#5F7A1F] mt-0.5 shrink-0" />}
          {t.type === "error" && <XCircle size={18} className="text-[#B20000] mt-0.5 shrink-0" />}
          {t.type === "info" && <Info size={18} className="text-[#4C7EFF] mt-0.5 shrink-0" />}
          <span className="text-gray-700 flex-1">{t.message}</span>
          <button onClick={() => remove(t.id)} className="text-gray-400 hover:text-[#666666]">
            <X size={14} />
          </button>
        </div>
      ))}
    </div>
  );
}

/* ============================================================
   MODAL + CONFIRM
   ============================================================ */
function Modal({ title, onClose, children, size = "md", footer }) {
  const sizes = { sm: "max-w-md", md: "max-w-xl", lg: "max-w-3xl", xl: "max-w-5xl" };
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40" onClick={onClose}>
      <div
        className={`bg-white rounded-xl shadow-2xl w-full ${sizes[size]} max-h-[90vh] flex flex-col`}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between px-6 py-4 border-b border-[#E6E6E6]">
          <h3 className="font-semibold text-gray-800 text-lg">{title}</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-[#666666] hover:bg-[#E6E6E6] rounded-lg p-1">
            <X size={20} />
          </button>
        </div>
        <div className="px-6 py-5 overflow-y-auto">{children}</div>
        {footer && <div className="px-6 py-4 border-t border-[#E6E6E6] flex justify-end gap-3">{footer}</div>}
      </div>
    </div>
  );
}

function ConfirmDialog({ open, title, message, danger, confirmLabel = "Confirmar", onConfirm, onCancel }) {
  if (!open) return null;
