/* ============================================================
   FORM ATOMS
   ============================================================ */
function Field({ label, required, error, children }) {
  return (
    <div className="mb-4">
      <label className="block text-sm font-medium text-gray-700 mb-1.5">
        {label} {required && <span className="text-[#FF4C4D]">*</span>}
      </label>
      {children}
      {error && <p className="text-xs text-[#B20000] mt-1">{error}</p>}
    </div>
  );
}
const inputCls = (error) =>
  `w-full px-3 py-2.5 rounded-lg border text-sm text-gray-800 focus:outline-none focus:ring-2 focus:ring-[#B20000]/40 focus:border-[#B20000] ${
    error ? "border-[#FF4C4D]/30" : "border-[#DADADA]"
  }`;

function TextInput(props) {
  const { error, ...rest } = props;
  return <input {...rest} className={inputCls(error)} />;
}
/* Select com pesquisa: listas com 8+ opções, e os campos de pessoas (aluno, responsável, orientador, usuário, marcados com "busca"), ganham um campo de busca.
   Listas curtas, de horários ou de números continuam como <select> nativo. Use busca={true|false} para forçar. */
const semAcento = (t) => String(t).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
function textoDe(n) {
  if (n == null || typeof n === "boolean") return "";
  if (Array.isArray(n)) return n.map(textoDe).join("");
  if (typeof n === "object" && n.props) return textoDe(n.props.children);
  return String(n);
}
function coletarOpcoes(children, out = []) {
  React.Children.forEach(children, (ch) => {
    if (!ch || !ch.type) return;
    if (ch.type === "option") {
      const label = textoDe(ch.props.children);
      out.push({ value: ch.props.value !== undefined ? String(ch.props.value) : label, label, disabled: !!ch.props.disabled });
    } else if (ch.props && ch.props.children) {
      coletarOpcoes(ch.props.children, out);
    }
  });
  return out;
}
function Select({ error, children, className, style, busca, ...rest }) {
  const opts = coletarOpcoes(children);
  const reais = opts.filter((o) => o.value !== ""); // ignora o "Selecione..."/"Todos" vazio
  const grande = reais.length >= 8 && !reais.every((o) => /^\d{1,2}:\d{2}$/.test(o.label) || /^\d+$/.test(o.label));
  if (busca === false || (busca !== true && !grande)) {
    return (
      <select {...rest} style={style} className={className || inputCls(error)}>
        {children}
      </select>
    );
  }
  return <SelectComBusca opts={opts} error={error} className={className} style={style} {...rest} />;
}
/* Seletor de horário com precisão de minutos que só deixa escolher minutos permitidos ("permitidos" = minutos do dia). */
function SeletorHorario({ value, onChange, permitidos, error, disabled, id }) {
  const horas = [...new Set(permitidos.map((m) => Math.floor(m / 60)))];
  const [hh, mm] = value ? value.split(":").map(Number) : [null, null];
  const minutosDaHora = permitidos.filter((m) => Math.floor(m / 60) === hh).map((m) => m % 60);
  const bloqueado = disabled || permitidos.length === 0;
  function mudaHora(e) {
    if (e.target.value === "") return onChange("");
    const h = Number(e.target.value);
    onChange(fromMin(permitidos.find((m) => Math.floor(m / 60) === h)));   // 1º minuto livre dessa hora
  }
  function mudaMin(e) {
    if (e.target.value === "") return onChange("");
    onChange(fromMin(hh * 60 + Number(e.target.value)));
  }
  return (
    <div className="flex items-center gap-2">
      <select id={id} aria-label="Hora" disabled={bloqueado} value={hh == null ? "" : String(hh)} onChange={mudaHora} className={inputCls(error)}>
        <option value="">--</option>
        {horas.map((h) => <option key={h} value={h}>{String(h).padStart(2, "0")}</option>)}
      </select>
      <span className="text-gray-500 font-semibold" aria-hidden="true">:</span>
      <select aria-label="Minutos" disabled={bloqueado || hh == null} value={mm == null ? "" : String(mm)} onChange={mudaMin} className={inputCls(error)}>
        <option value="">--</option>
        {minutosDaHora.map((m) => <option key={m} value={m}>{String(m).padStart(2, "0")}</option>)}
      </select>
    </div>
  );
}

/* Escolha múltipla com pesquisa e "etiquetas" removíveis (usada para os responsáveis do aluno). */
function MultiPick({ opcoes, valor, onChange, error }) {
  const [q, setQ] = useState("");
  const lista = opcoes.filter((o) => !q || semAcento(o.nome).includes(semAcento(q)));
  const alternar = (id) => onChange(valor.includes(id) ? valor.filter((x) => x !== id) : [...valor, id]);
  const nome = (id) => (opcoes.find((o) => o.id === id) || {}).nome || id;
  return (
    <div>
      {valor.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mb-2">
          {valor.map((id) => (
            <span key={id} className="inline-flex items-center gap-1 pl-2.5 pr-1 py-0.5 rounded-full bg-[#B20000]/10 text-[#7E0000] text-xs">
              {nome(id)}
              <button type="button" aria-label={`Remover ${nome(id)}`} onClick={() => alternar(id)} className="p-0.5 rounded-full hover:bg-[#B20000]/20"><X size={12} /></button>
            </span>
          ))}
        </div>
      )}
      <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Pesquisar pelo nome" aria-label="Pesquisar responsável" className={inputCls() + " mb-2"} />
      <div className={`max-h-40 overflow-y-auto border rounded-lg divide-y divide-[#E6E6E6] ${error ? "border-[#B20000]" : "border-[#DADADA]"}`}>
        {lista.map((o) => (
          <label key={o.id} className="flex items-center gap-2 px-3 py-2 text-sm cursor-pointer hover:bg-[#F8F8F8]">
            <input type="checkbox" checked={valor.includes(o.id)} onChange={() => alternar(o.id)} className="accent-[#B20000]" />
            {o.nome}
          </label>
        ))}
        {lista.length === 0 && <p className="px-3 py-3 text-sm text-[#666666]">Ninguém encontrado.</p>}
      </div>
    </div>
  );
}

/* Desenha o painel fora do formulário/modal quando possível (evita corte por overflow); sem createPortal, desenha no lugar. */
function noPortal(elemento) {
  return typeof window.__createPortal === "function" ? window.__createPortal(elemento, document.body) : elemento;
}
function SelectComBusca({ opts, error, className, style, value, onChange, disabled, id, name, ...rest }) {
  const [aberto, setAberto] = useState(false);
  const [q, setQ] = useState("");
  const [ativo, setAtivo] = useState(0);
  const [pos, setPos] = useState(null);
  const btn = useRef(null), painel = useRef(null), campo = useRef(null);
  const listaId = useRef("sel-" + Math.random().toString(36).slice(2, 8)).current;
  const atual = opts.find((o) => o.value === String(value == null ? "" : value));
  const filtradas = opts.filter((o) => !q || semAcento(o.label).includes(semAcento(q)));

  function posicionar() {
    if (!btn.current) return;
    const r = btn.current.getBoundingClientRect();
    const abaixo = window.innerHeight - r.bottom, acima = r.top;
    const sobe = abaixo < 280 && acima > abaixo;
    setPos({
      left: Math.max(8, Math.min(r.left, window.innerWidth - Math.max(r.width, 224) - 8)), width: Math.max(r.width, 224),
      top: sobe ? undefined : r.bottom + 4, bottom: sobe ? window.innerHeight - r.top + 4 : undefined,
      max: Math.max(180, (sobe ? acima : abaixo) - 16), font: window.getComputedStyle(btn.current).fontFamily,
    });
  }
  function abrir() {
    if (disabled) return;
    setQ("");
    setAtivo(Math.max(0, opts.findIndex((o) => o.value === String(value == null ? "" : value))));
    posicionar();
    setAberto(true);
  }
  function fechar(foco) {
    setAberto(false);
    if (foco !== false && btn.current) btn.current.focus();
  }
  function escolher(o) {
    if (o.disabled) return;
    if (onChange) onChange({ target: { value: o.value, name }, currentTarget: { value: o.value, name } });
    fechar();
  }
  useEffect(() => {
    if (!aberto) return undefined;
    const fora = (e) => {
      if ((painel.current && painel.current.contains(e.target)) || (btn.current && btn.current.contains(e.target))) return;
      setAberto(false);
    };
    document.addEventListener("mousedown", fora);
    window.addEventListener("resize", posicionar);
    window.addEventListener("scroll", posicionar, true);
    const t = setTimeout(() => campo.current && campo.current.focus(), 0);
    return () => {
      clearTimeout(t);
      document.removeEventListener("mousedown", fora);
      window.removeEventListener("resize", posicionar);
      window.removeEventListener("scroll", posicionar, true);
    };
  }, [aberto]);
  useEffect(() => {
    const el = painel.current && painel.current.querySelector('[data-ativo="true"]');
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest" });
  }, [ativo, aberto]);

  function teclas(e) {
    if (e.key === "ArrowDown") { e.preventDefault(); setAtivo((i) => Math.min(i + 1, Math.max(0, filtradas.length - 1))); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setAtivo((i) => Math.max(i - 1, 0)); }
    else if (e.key === "Enter") { e.preventDefault(); if (filtradas[ativo]) escolher(filtradas[ativo]); }
    else if (e.key === "Escape") { e.preventDefault(); fechar(); }
    else if (e.key === "Tab") { setAberto(false); }
  }

  return (
    <>
      <button
        type="button" ref={btn} id={id} disabled={disabled} role="combobox" aria-haspopup="listbox"
        aria-expanded={aberto} aria-controls={aberto ? listaId : undefined} aria-label={rest["aria-label"]}
        onClick={() => (aberto ? fechar(false) : abrir())}
        onKeyDown={(e) => { if (e.key === "ArrowDown" || e.key === "ArrowUp") { e.preventDefault(); abrir(); } }}
        style={style} className={`${className || inputCls(error)} flex items-center justify-between gap-2 text-left`}
      >
        <span className="truncate">{atual ? atual.label : "Selecione..."}</span>
        <ChevronDown size={16} className="shrink-0 text-gray-400" />
      </button>
      {aberto && pos && noPortal(
        <div ref={painel} style={{ position: "fixed", left: pos.left, width: pos.width, top: pos.top, bottom: pos.bottom, zIndex: 70, fontFamily: pos.font }}
          className="bg-white border border-[#DADADA] rounded-lg shadow-lg">
          <div className="p-2 border-b border-[#E6E6E6] flex items-center gap-2">
            <Search size={15} className="text-gray-400 shrink-0" />
            <input
              ref={campo} value={q} onChange={(e) => { setQ(e.target.value); setAtivo(0); }} onKeyDown={teclas}
              placeholder="Pesquisar..." aria-label="Pesquisar na lista" aria-controls={listaId} className="w-full text-sm outline-none"
            />
          </div>
          <ul id={listaId} role="listbox" style={{ maxHeight: Math.max(120, pos.max - 52) }} className="overflow-y-auto py-1">
            {filtradas.map((o, i) => (
              <li
                key={o.value + "-" + i} role="option" aria-selected={atual ? atual.value === o.value : false} data-ativo={i === ativo ? "true" : "false"}
                onMouseDown={(e) => e.preventDefault()} onClick={() => escolher(o)} onMouseEnter={() => setAtivo(i)}
                className={`px-3 py-2 text-sm cursor-pointer ${i === ativo ? "bg-[#B20000]/10" : ""} ${atual && atual.value === o.value ? "font-semibold text-[#B20000]" : "text-gray-700"} ${o.disabled ? "opacity-40" : ""}`}
              >
                {o.label || "—"}
              </li>
            ))}
            {filtradas.length === 0 && <li className="px-3 py-3 text-sm text-[#666666]">Nenhum resultado</li>}
          </ul>
        </div>
      )}
    </>
  );
}
function TextArea({ error, ...rest }) {
  return <textarea {...rest} className={inputCls(error)} rows={3} />;
}

