/* ============================================================
   EMPTY STATE + SKELETON
   ============================================================ */
function EmptyState({ icon: Icon = ClipboardList, title, message }) {
  return (
    <div className="flex flex-col items-center justify-center py-14 text-center">
      <div className="w-14 h-14 rounded-full bg-[#F8F8F8] flex items-center justify-center mb-3">
        <Icon size={24} className="text-gray-300" />
      </div>
      <p className="font-medium text-[#666666]">{title}</p>
      {message && <p className="text-sm text-gray-400 mt-1 max-w-xs">{message}</p>}
    </div>
