}
function SkeletonRows({ cols = 5, rows = 6 }) {
  return (
    <>
      {Array.from({ length: rows }).map((_, r) => (
        <tr key={r} className="border-b border-[#E6E6E6]">
          {Array.from({ length: cols }).map((_, c) => (
            <td key={c} className="px-4 py-3.5">
              <div className="h-3.5 rounded bg-[#E6E6E6] animate-pulse" style={{ width: `${50 + ((r + c) % 4) * 12}%` }} />
            </td>
          ))}
        </tr>
      ))}
    </>
  );
}

/* ============================================================
   DATA TABLE + TOOLBAR
   ============================================================ */
function DataTable({ columns, rows, loading, emptyTitle, emptyMessage, rowKey = "id" }) {
  const [visibleCount, setVisibleCount] = useState(20);
  useEffect(() => { setVisibleCount(20); }, [rows.length]);
  const visibleRows = rows.slice(0, visibleCount);
  return (
    <div className="bg-white rounded-xl border border-[#E6E6E6] shadow-sm overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-[#F8F8F8] border-b border-[#E6E6E6]">
              {columns.map((c) => (
                <th key={c.key} className="text-left px-4 py-3 font-medium text-[#666666] text-xs uppercase tracking-wide whitespace-nowrap">
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <SkeletonRows cols={columns.length} />
            ) : rows.length === 0 ? null : (
              visibleRows.map((row) => (
                <tr key={row[rowKey]} className="border-b border-[#E6E6E6] last:border-0 hover:bg-[#F8F8F8] transition-colors">
                  {columns.map((c) => (
                    <td key={c.key} className="px-4 py-3.5 text-gray-700 whitespace-nowrap">
                      {c.render ? c.render(row) : row[c.key]}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      {!loading && rows.length === 0 && <EmptyState title={emptyTitle || "Nenhum resultado encontrado"} message={emptyMessage || "Ajuste os filtros ou cadastre um novo registro."} />}
      {!loading && rows.length > visibleCount && <div className="flex justify-center border-t border-[#E6E6E6] p-3"><button type="button" onClick={() => setVisibleCount((n) => n + 20)} className="px-4 py-2 rounded-lg border border-[#DADADA] text-sm font-medium text-[#7E0000] hover:bg-[#B20000]/5">Carregar mais ({Math.min(20, rows.length - visibleCount)} de {rows.length - visibleCount})</button></div>}
    </div>
  );
}

function IconBtn({ icon: Icon, onClick, title, tone = "default" }) {
  const tones = {
    default: "text-[#666666] hover:text-[#B20000] hover:bg-[#B20000]/10",
    danger: "text-[#666666] hover:text-[#B20000] hover:bg-[#FF4C4D]/10",
  };
  return (
    <button onClick={onClick} title={title} className={`p-1.5 rounded-lg transition-colors ${tones[tone]}`}>
      <Icon size={16} />
    </button>
  );
}

