    e.preventDefault();
    setRegError("");
    if (!regNome || !regEmail || !regTelefone || !regCpf || !regSenha || !regConfirmar) {
      setRegError("Preencha todos os campos para continuar.");
      return;
    }
    if (!isValidEmail(regEmail)) {
      setRegError("Informe um e-mail válido.");
      return;
