/* ============================================================
   DEMONSTRAÇÃO TEMPORÁRIA (sessionStorage)
   Os dados ficam disponíveis durante esta aba do navegador.
   O sessionStorage sobrevive a recargas, mas é apagado ao fechar a aba.
   ============================================================ */
const DEMO_SESSION_KEY = "sigep_demo_session_v2";
function carregarEstadoDemo() {
  const base = buildSeed();
  const extraBase = seedExtra(base);
  try {
    const salvo = JSON.parse(sessionStorage.getItem(DEMO_SESSION_KEY) || "null");
    if (salvo && salvo.data && typeof salvo.data === "object") {
      return {
        seed: { ...base, ...salvo.data },
        extra: { ...extraBase, ...(salvo.extra || {}) },
      };
    }
  } catch (erro) {
    console.warn("Não foi possível recuperar os dados temporários do SIGEP. Uma nova demonstração será iniciada.", erro);
  }
  return { seed: base, extra: extraBase };
}
function salvarEstadoDemo(data, extra) {
  try {
    sessionStorage.setItem(DEMO_SESSION_KEY, JSON.stringify({ data, extra, atualizadoEm: new Date().toISOString() }));
  } catch (erro) {
    console.warn("Não foi possível salvar os dados temporários desta sessão.", erro);
  }
}

/* ============================================================
   ROOT APP
   ============================================================ */
function SigepApp() {
  const [estadoInicial] = useState(carregarEstadoDemo);
  const seed = estadoInicial.seed;
  const extra = estadoInicial.extra;
  const [instituicao, setInstituicao] = useState(seed.instituicao);
  const [responsaveis, setResponsaveis] = useState(seed.responsaveis);
  const [orientadores, setOrientadores] = useState(seed.orientadores);
  const [alunos, setAlunos] = useState(seed.alunos);
  const [responsavelAluno, setResponsavelAluno] = useState(seed.responsavelAluno);
  const [atendimentos, setAtendimentos] = useState(seed.atendimentos);
  const [notificacoes, setNotificacoes] = useState(seed.notificacoes);
  const [admins, setAdmins] = useState(extra.admins);
  const [disponibilidades, setDisponibilidades] = useState(extra.disp);
  const [reunioes, setReunioes] = useState(extra.reunioes);
  const [auditoria, setAuditoria] = useState(extra.audit);

  // Simulação sem banco: todas as alterações funcionais são mantidas apenas nesta aba.
  // Ao fechar a aba/janela, o navegador elimina automaticamente o sessionStorage.
  useEffect(() => {
    salvarEstadoDemo(
      { instituicao, responsaveis, orientadores, alunos, responsavelAluno, atendimentos, notificacoes },
      { admins, disp: disponibilidades, reunioes, audit: auditoria }
    );
  }, [instituicao, responsaveis, orientadores, alunos, responsavelAluno, atendimentos, notificacoes, admins, disponibilidades, reunioes, auditoria]);

  const [role, setRole] = useState(null);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [page, setPageRaw] = useState("dashboard");
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [loadingPage, setLoadingPage] = useState(false);
  const [toasts, setToasts] = useState([]);
  const [confirmState, setConfirmState] = useState(null);

  const [a11y, setA11yState] = useState(loadA11y);
  function setA11y(patch) { setA11yState((prev) => ({ ...prev, ...(typeof patch === "function" ? patch(prev) : patch) })); }
  REDUCE_MOTION = a11y.motion === "reduce" || (a11y.motion === "system" && prefersReducedMotion());
  useEffect(() => { applyA11y(a11y); saveA11y(a11y); }, [a11y]);
  useEffect(() => {
    if (!window.matchMedia) return undefined;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setA11yState((prev) => ({ ...prev }));
    if (mq.addEventListener) mq.addEventListener("change", onChange);
    return () => { if (mq.removeEventListener) mq.removeEventListener("change", onChange); };
  }, []);

  function addToast(message, type = "success") {
    const id = uid("t");
    setToasts((t) => [...t, { id, message, type }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3200);
  }
  function removeToast(id) {
    setToasts((t) => t.filter((x) => x.id !== id));
  }
  function setPage(p) {
    setLoadingPage(true);
    setPageRaw(p);
    setTimeout(() => setLoadingPage(false), 420);
  }
  function askConfirm(opts) {
    setConfirmState(opts);
  }

  function handleLogin(loggedRole) {
    setRole(loggedRole);
    if (loggedRole === "orientador") setCurrentUserId("O001");
    if (loggedRole === "responsavel") setCurrentUserId("R001");
    if (loggedRole === "instituicao") setCurrentUserId("INST");
    setPageRaw("dashboard");
    addToast("Login realizado com sucesso. Bem-vindo(a)!", "success");
  }
  function handleLogout() {
    // Ao sair explicitamente, encerra também a demonstração temporária desta aba.
    try { sessionStorage.removeItem(DEMO_SESSION_KEY); } catch (erro) {}
    window.location.reload();
  }

  function handleSignup(data) {
    const emailJaExiste =
      responsaveis.some((r) => r.email.toLowerCase() === data.email.trim().toLowerCase()) ||
      orientadores.some((o) => o.email.toLowerCase() === data.email.trim().toLowerCase()) ||
      DEMO_ACCOUNTS.some((a) => a.email.toLowerCase() === data.email.trim().toLowerCase());
    if (emailJaExiste) {
      return "Já existe uma conta cadastrada com este e-mail.";
    }
    const novo = {
      id: uid("R"),
      nome: data.nome,
      cpf: data.cpf,
      email: data.email.trim().toLowerCase(),
      telefone: data.telefone,
      senha: data.senha,
      status: "Ativo",
    };
    setResponsaveis((prev) => [...prev, novo]);
    setRole("responsavel");
    setCurrentUserId(novo.id);
    setPageRaw("dashboard");
    addToast("Cadastro realizado com sucesso. Bem-vindo(a)!", "success");
    return null;
  }

  const currentUser = useMemo(() => {
    if (role === "instituicao") return { nome: "Etec Heliópolis", iniciais: "EH", email: instituicao.email };
    if (role === "orientador") {
      const o = orientadores.find((x) => x.id === currentUserId);
      return o ? { nome: o.nome, iniciais: o.nome.replace("Prof. ", "").replace("Profa. ", "").split(" ").map((w) => w[0]).slice(0, 2).join(""), email: o.email, raw: o } : null;
    }
    if (role === "responsavel") {
      const r = responsaveis.find((x) => x.id === currentUserId);
      return r ? { nome: r.nome, iniciais: r.nome.split(" ").map((w) => w[0]).slice(0, 2).join(""), email: r.email, raw: r } : null;
    }
    return null;
  }, [role, currentUserId, orientadores, responsaveis, instituicao]);

  const notifCount = useMemo(
    () => notificacoes.filter((n) => n.responsavelId === currentUserId && !n.lida).length,
    [notificacoes, currentUserId]
  );

  // Auditoria e notificações automáticas: observam as listas e registram o que mudou.
  // Na integração com o back-end, estes dois pontos passam a chamar a API (PHP/MySQL).
  function logAudit(acao, cat) {
    setAuditoria((p) => [{ id: uid("L"), usuario: currentUser ? currentUser.nome : "Sistema", perfil: role ? PERFIS[role] : "-", acao, cat, quando: new Date().toISOString() }, ...p]);
  }
  function notify(destinos, texto, cat) {
    const ids = [...new Set(destinos)].filter((x) => x && x !== currentUserId);
    if (!ids.length) return;
    setNotificacoes((p) => [...ids.map((id) => ({ id: uid("N"), responsavelId: id, texto, lida: false, data: dateKey(TODAY), cat })), ...p]);
  }
  const pessoaNome = (id) => ([...admins, ...orientadores, ...responsaveis].find((x) => x.id === id) || {}).nome || id;
  // leitura dos vínculos N:N aluno ⇄ responsável
  const respIdsDe = (rm) => responsavelAluno.filter((v) => v.alunoRm === rm).map((v) => v.responsavelId);
  const alunosDoResp = (rid) => alunos.filter((a) => responsavelAluno.some((v) => v.alunoRm === a.rm && v.responsavelId === rid));
  const nomesRespDe = (rm) => respIdsDe(rm).map((id) => responsavelNome(responsaveis, id)).join(", ") || "—";
  const usuarioLog = (rotulo) => ({
    add: (x) => logAudit(`Cadastrou ${rotulo} ${x.nome}`, "Usuários"),
    chg: (o, x) => logAudit(o.status !== x.status ? `${x.status === "Ativo" ? "Reativou" : "Desativou"} ${rotulo} ${x.nome}` : `Alterou dados de ${rotulo} ${x.nome}`, "Usuários"),
    del: (o) => logAudit(`Excluiu ${rotulo} ${o.nome}`, "Usuários"),
  });
  useDiff(responsaveis, "id", usuarioLog("responsável"));
  useDiff(orientadores, "id", usuarioLog("orientador"));
  useDiff(admins, "id", usuarioLog("administrador"));
  useDiff(alunos, "rm", {
    add: (x) => logAudit(`Cadastrou o aluno ${x.nome}`, "Alunos"),
    chg: (o, x) => logAudit(`Alterou dados do aluno ${x.nome}`, "Alunos"),
    del: (o) => logAudit(`Excluiu o aluno ${o.nome}`, "Alunos"),
  });
  useDiff(atendimentos, "id", {
    add: (x) => {
      const al = alunoNome(alunos, x.alunoRm);
      if (x.status !== "Pendente") {
        logAudit(`Agendou atendimento direto (${al}) para ${formatDate(x.data)} às ${x.horario}`, "Agendamentos");
        notify([...respIdsDe(x.alunoRm), x.responsavelId, x.orientadorId, "INST"], `Atendimento de ${al} agendado para ${formatDate(x.data)} às ${x.horario}.`, "Agendamentos");
        return;
      }
      logAudit(`Nova solicitação de atendimento (${al}) para ${formatDate(x.data)} às ${x.horario}`, "Solicitações");
      notify([x.orientadorId, "INST"], `Nova solicitação de atendimento: ${al}, ${formatDate(x.data)} às ${x.horario}.`, "Solicitações");
    },
    chg: (o, x) => {
      const al = alunoNome(alunos, x.alunoRm), quem = [...respIdsDe(x.alunoRm), x.responsavelId, x.orientadorId, "INST"];
      if (o.status !== x.status) {
        const t = { Confirmado: ["aprovada", "Solicitações"], Recusado: ["recusada", "Solicitações"], Cancelado: ["cancelado", "Agendamentos"], Finalizado: ["finalizado e registrado", "Atendimentos"], "Em Andamento": ["iniciado", "Atendimentos"] }[x.status];
        if (!t) return;
        logAudit(`Atendimento de ${al} (${formatDate(x.data)}): ${o.status} → ${x.status}`, t[1]);
        notify(quem, `O atendimento de ${al} em ${formatDate(x.data)} às ${x.horario} foi ${t[0]}.`, t[1]);
      } else if (o.data !== x.data || o.horario !== x.horario) {
        logAudit(`Agendamento de ${al} alterado para ${formatDate(x.data)} às ${x.horario}`, "Agendamentos");
        notify(quem, `O agendamento de ${al} foi alterado para ${formatDate(x.data)} às ${x.horario}.`, "Agendamentos");
      }
    },
  });
  useDiff(reunioes, "id", {
    add: (x) => { logAudit(`Cadastrou a reunião "${x.assunto}"`, "Reuniões"); notify(x.participantes, `Você foi convidado(a) para a reunião "${x.assunto}" em ${formatDate(x.data)} às ${x.horario}.`, "Reuniões"); },
    chg: (o, x) => {
      const canc = x.status === "Cancelada" && o.status !== "Cancelada";
      logAudit(`${canc ? "Cancelou" : "Alterou"} a reunião "${x.assunto}"`, "Reuniões");
      notify(x.participantes, `A reunião "${x.assunto}" foi ${canc ? "cancelada" : "alterada"}.`, "Reuniões");
    },
  });
  useDiff(disponibilidades, "id", {
    add: (x) => logAudit(`Cadastrou disponibilidade de ${pessoaNome(x.orientadorId)}: ${DIAS[x.dia]}, ${x.inicio}–${x.fim}`, "Disponibilidade"),
    chg: (o, x) => logAudit(`Alterou disponibilidade de ${pessoaNome(x.orientadorId)}: ${DIAS[x.dia]}, ${x.inicio}–${x.fim}`, "Disponibilidade"),
    del: (o) => logAudit(`Excluiu disponibilidade de ${pessoaNome(o.orientadorId)}: ${DIAS[o.dia]}, ${o.inicio}–${o.fim}`, "Disponibilidade"),
  });

  if (!role || !currentUser) {
    return <LoginPage onLogin={handleLogin} onSignup={handleSignup} />;
  }

  const ctx = {
    instituicao, setInstituicao,
    responsaveis, setResponsaveis,
    orientadores, setOrientadores,
    alunos, setAlunos,
    atendimentos, setAtendimentos,
    notificacoes, setNotificacoes,
    addToast, askConfirm, role, currentUserId, currentUser, setPage,
    a11y, setA11y,
    responsavelAluno, setResponsavelAluno, respIdsDe, alunosDoResp, nomesRespDe,
    admins, setAdmins, disponibilidades, setDisponibilidades, reunioes, setReunioes, auditoria, logAudit, notify,
  };

  return (
    <div className="min-h-screen bg-[#F8F8F8] flex" style={{ fontFamily: "Inter, system-ui, -apple-system, sans-serif" }}>
      <Sidebar role={role} page={page} setPage={setPage} collapsed={collapsed} setCollapsed={setCollapsed} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} />
      <div className="flex-1 min-w-0 flex flex-col">
        <Header user={currentUser} role={role} page={page} onLogout={() => askConfirm({
          title: "Sair do SIGEP",
          message: "Tem certeza de que deseja encerrar sua sessão?",
          confirmLabel: "Sair",
          danger: false,
          onConfirm: () => { setConfirmState(null); handleLogout(); },
        })} setMobileOpen={setMobileOpen} notifCount={notifCount} setPage={setPage} />
        <main className="flex-1 p-4 lg:p-6 max-w-[87.5rem] w-full mx-auto">
          {loadingPage ? <PageSkeleton /> : <PageRouter page={page} ctx={ctx} />}
        </main>
      </div>
      <ToastStack toasts={toasts} remove={removeToast} />
      <ConfirmDialog
        open={!!confirmState}
        title={confirmState?.title}
        message={confirmState?.message}
        danger={confirmState?.danger}
        confirmLabel={confirmState?.confirmLabel}
        onConfirm={confirmState?.onConfirm}
        onCancel={() => setConfirmState(null)}
      />
    </div>
  );
}

function PageSkeleton() {
  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {Array.from({ length: 4 }).map((_, i) => (
          <div key={i} className="h-20 bg-white rounded-xl border border-[#E6E6E6] animate-pulse" />
        ))}
      </div>
      <div className="h-72 bg-white rounded-xl border border-[#E6E6E6] animate-pulse" />
    </div>
  );
}

/* ============================================================
   PAGE ROUTER
   ============================================================ */
function PageRouter({ page, ctx }) {
  const { role } = ctx;
  if (role === "instituicao") {
    switch (page) {
      case "dashboard": return <InstDashboard ctx={ctx} />;
      case "alunos": return <AlunosPage ctx={ctx} editable />;
      case "responsaveis": return <ResponsaveisPage ctx={ctx} />;
      case "orientadores": return <OrientadoresPage ctx={ctx} />;
      case "agendamentos": return <AgendamentosPage ctx={ctx} scope="all" />;
      case "reunioes": return <ReunioesPage ctx={ctx} />;
      case "historico": return <HistoricoInstituicaoPage ctx={ctx} />;
      case "relatorios": return <RelatoriosPage ctx={ctx} scope="all" />;
      case "instituicao": return <InstituicaoPage ctx={ctx} />;
      case "perfil": return <PerfilPage ctx={ctx} />;
      case "configuracoes": return <ConfiguracoesPage ctx={ctx} />;
      case "usuarios": return <UsuariosPage ctx={ctx} />;
      case "disponibilidade": return <DisponibilidadePage ctx={ctx} scope="all" />;
      case "auditoria": return <AuditoriaPage ctx={ctx} />;
      case "notificacoes": return <NotificacoesPage ctx={ctx} />;
      default: return null;
    }
  }
  if (role === "orientador") {
    switch (page) {
      case "dashboard": return <OrientDashboard ctx={ctx} />;
      case "alunos": return <AlunosPage ctx={ctx} editable={false} />;
      case "agendamentos": return <AgendamentosPage ctx={ctx} scope="mine" />;
      case "atendimentos": return <AtendimentosPage ctx={ctx} scope="mine" />;
      case "relatorios": return <RelatoriosPage ctx={ctx} scope="mine" />;
      case "perfil": return <PerfilPage ctx={ctx} />;
      case "solicitacoes": return <SolicitacoesPage ctx={ctx} scope="mine" />;
      case "disponibilidade": return <DisponibilidadePage ctx={ctx} scope="mine" />;
      case "reunioes": return <ReunioesPage ctx={ctx} />;
      case "notificacoes": return <NotificacoesPage ctx={ctx} />;
      default: return null;
    }
  }
  if (role === "responsavel") {
    switch (page) {
      case "dashboard": return <RespDashboard ctx={ctx} />;
      case "meus-alunos": return <MeusAlunosPage ctx={ctx} />;
      case "solicitar": return <SolicitarPage ctx={ctx} />;
      case "agendamentos": return <RespAgendamentosPage ctx={ctx} />;
      case "historico": return <RespHistoricoPage ctx={ctx} />;
      case "notificacoes": return <NotificacoesPage ctx={ctx} />;
      case "perfil": return <PerfilPage ctx={ctx} />;
      default: return null;
    }
  }
  return null;
}

/* ============================================================
   HELPERS: derived lookups
   ============================================================ */
function alunoNome(alunos, rm) {
  const a = alunos.find((x) => x.rm === rm);
  return a ? a.nome : "—";
}
function orientadorNome(orientadores, id) {
  const o = orientadores.find((x) => x.id === id);
  return o ? o.nome : "—";
}
function responsavelNome(responsaveis, id) {
  const r = responsaveis.find((x) => x.id === id);
  return r ? r.nome : "—";
}
function last6Months() {
  const arr = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(TODAY.getFullYear(), TODAY.getMonth() - i, 1);
    arr.push({ key: `${d.getFullYear()}-${d.getMonth()}`, label: d.toLocaleDateString("pt-BR", { month: "short" }) });
  }
  return arr;
}

/* ============================================================
   INSTITUIÇÃO — DASHBOARD
   ============================================================ */
function InstDashboard({ ctx }) {
  const { alunos, responsaveis, orientadores, atendimentos } = ctx;
  const agendados = atendimentos.filter((a) => a.status === "Confirmado").length;
  const realizados = atendimentos.filter((a) => a.status === "Finalizado").length;
  const cancelados = atendimentos.filter((a) => a.status === "Cancelado").length;

  const meses = last6Months();
  const porMes = meses.map((m) => ({
    mes: m.label,
    total: atendimentos.filter((a) => {
      const d = parseDay(a.data);
      return `${d.getFullYear()}-${d.getMonth()}` === m.key;
    }).length,
  }));
  const porOrientador = orientadores.map((o) => ({
    nome: o.nome.replace("Prof. ", "").replace("Profa. ", ""),
    total: atendimentos.filter((a) => a.orientadorId === o.id).length,
  }));
  const porCurso = CURSOS.map((c) => ({
    curso: c,
    total: atendimentos.filter((a) => {
      const al = alunos.find((x) => x.rm === a.alunoRm);
      return al && al.curso === c;
    }).length,
  })).filter((c) => c.total > 0);

  const recentes = [...atendimentos].sort((a, b) => (a.data < b.data ? 1 : -1)).slice(0, 6);

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard icon={GraduationCap} label="Total de alunos" value={alunos.length} tint="bg-[#4C7EFF]/10 text-[#4C7EFF]" />
        <StatCard icon={Users} label="Total de responsáveis" value={responsaveis.length} tint="bg-[#8A29E6]/10 text-[#8A29E6]" />
        <StatCard icon={UserCheck} label="Total de orientadores" value={orientadores.length} tint="bg-[#B20000]/10 text-[#B20000]" />
        <StatCard icon={ClipboardList} label="Total de atendimentos" value={atendimentos.length} tint="bg-[#FFC24C]/15 text-[#A66F00]" />
        <StatCard icon={CalendarClock} label="Agendados" value={agendados} tint="bg-[#4C7EFF]/10 text-[#4C7EFF]" />
        <StatCard icon={CalendarCheck} label="Realizados" value={realizados} tint="bg-[#A0C340]/15 text-[#5F7A1F]" />
        <StatCard icon={CalendarX} label="Cancelados" value={cancelados} tint="bg-[#FF4C4D]/10 text-[#B20000]" />
        <StatCard icon={Clock} label="Pendentes" value={atendimentos.filter((a) => a.status === "Pendente").length} tint="bg-[#FFC24C]/15 text-[#A66F00]" />
      </div>

      <div className="grid lg:grid-cols-3 gap-4">
        <ChartCard title="Atendimentos por mês" className="lg:col-span-2">
          <ResponsiveContainer width="100%" height={240}>
            <LineChart data={porMes}>
              <CartesianGrid strokeDasharray="3 3" stroke="#E6E6E6" />
              <XAxis dataKey="mes" tick={{ fontSize: 12, fill: "#666666" }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fontSize: 12, fill: "#666666" }} axisLine={false} tickLine={false} allowDecimals={false} />
              <Tooltip />
              <Line isAnimationActive={!REDUCE_MOTION} type="monotone" dataKey="total" stroke="#B20000" strokeWidth={2.5} dot={{ r: 3 }} />
            </LineChart>
          </ResponsiveContainer>
        </ChartCard>
        <ChartCard title="Por orientador">
          <ResponsiveContainer width="100%" height={240}>
            <PieChart>
              <Pie isAnimationActive={!REDUCE_MOTION} data={porOrientador} dataKey="total" nameKey="nome" innerRadius={45} outerRadius={75} paddingAngle={2}>
                {porOrientador.map((_, i) => (
                  <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>

      <div className="grid lg:grid-cols-3 gap-4">
        <ChartCard title="Atendimentos por curso" className="lg:col-span-2">
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={porCurso} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#E6E6E6" horizontal={false} />
              <XAxis type="number" tick={{ fontSize: 12, fill: "#666666" }} axisLine={false} tickLine={false} allowDecimals={false} />
              <YAxis type="category" dataKey="curso" tick={{ fontSize: 11, fill: "#666666" }} axisLine={false} tickLine={false} width={140} />
              <Tooltip />
              <Bar isAnimationActive={!REDUCE_MOTION} dataKey="total" fill="#7E0000" radius={[0, 4, 4, 0]} barSize={16} />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>

        <div className="bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-4">
          <p className="font-medium text-gray-700 mb-3 text-sm">Atendimentos recentes</p>
          <div className="space-y-3">
            {recentes.map((a) => (
              <div key={a.id} className="flex items-center justify-between text-sm">
                <div className="min-w-0">
                  <p className="text-gray-700 truncate">{alunoNome(ctx.alunos, a.alunoRm)}</p>
                  <p className="text-xs text-gray-400">{formatDate(a.data)} · {a.horario}</p>
                </div>
                <Badge status={a.status} />
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function ChartCard({ title, children, className = "" }) {
  return (
    <div className={`bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-4 ${className}`}>
      <p className="font-medium text-gray-700 mb-2 text-sm">{title}</p>
      {children}
    </div>
  );
}

/* ============================================================
   ALUNOS (list, view, add/edit)
   ============================================================ */
function AlunosPage({ ctx, editable }) {
  const { alunos, setAlunos, responsaveis, atendimentos, addToast, askConfirm } = ctx;
  const [search, setSearch] = useState("");
  const [cursoFiltro, setCursoFiltro] = useState("");
  const [sortKey, setSortKey] = useState("nome");
  const [modal, setModal] = useState(null); // 'add' | 'edit' | 'view'
  const [selected, setSelected] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    setLoading(true);
    const t = setTimeout(() => setLoading(false), 400);
    return () => clearTimeout(t);
  }, [search, cursoFiltro]);

  const rows = useMemo(() => {
    let r = alunos.filter((a) => {
      const matchSearch = !search || a.nome.toLowerCase().includes(search.toLowerCase()) || a.rm.includes(search);
      const matchCurso = !cursoFiltro || a.curso === cursoFiltro;
      return matchSearch && matchCurso;
    });
    r.sort((a, b) => (a[sortKey] > b[sortKey] ? 1 : -1));
    return r;
  }, [alunos, search, cursoFiltro, sortKey]);

  function qtdAtendimentos(rm) {
    return atendimentos.filter((a) => a.alunoRm === rm).length;
  }

  const columns = [
    { key: "rm", label: "RM" },
    { key: "nome", label: "Nome" },
    { key: "ano", label: "Ano" },
    { key: "curso", label: "Curso" },
    { key: "periodo", label: "Período" },
    { key: "responsavel", label: "Responsáveis", render: (r) => ctx.nomesRespDe(r.rm) },
    { key: "qtd", label: "Atendimentos", render: (r) => qtdAtendimentos(r.rm) },
    {
      key: "acoes", label: "Ações", render: (r) => (
        <div className="flex items-center gap-0.5">
          <IconBtn icon={Eye} title="Visualizar" onClick={() => { setSelected(r); setModal("view"); }} />
          {editable && <IconBtn icon={Pencil} title="Editar" onClick={() => { setSelected(r); setModal("edit"); }} />}
          {editable && (
            <IconBtn
              icon={Trash2}
              title="Excluir"
              tone="danger"
              onClick={() =>
                askConfirm({
                  title: "Excluir aluno",
                  message: `Tem certeza de que deseja excluir o aluno "${r.nome}"? Esta ação não poderá ser desfeita.`,
                  danger: true,
                  confirmLabel: "Excluir",
                  onConfirm: () => {
                    setAlunos((prev) => prev.filter((x) => x.rm !== r.rm));
                    ctx.setResponsavelAluno((prev) => prev.filter((v) => v.alunoRm !== r.rm));
                    addToast("Aluno excluído com sucesso.", "success");
                    ctx.setConfirmClose && ctx.setConfirmClose();
                  },
                })
              }
            />
          )}
        </div>
      ),
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-2 justify-between">
        <div className="flex flex-wrap items-center gap-2">
          <div className="relative">
            <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar por nome ou RM..." className="pl-9 pr-3 py-2 rounded-lg border border-[#DADADA] text-sm w-64 focus:outline-none focus:ring-2 focus:ring-[#B20000]/40" />
          </div>
          <Select value={cursoFiltro} onChange={(e) => setCursoFiltro(e.target.value)} className="py-2 px-3 rounded-lg border border-[#DADADA] text-sm text-[#666666]">
            <option value="">Todos os cursos</option>
            {CURSOS.map((c) => <option key={c} value={c}>{c}</option>)}
          </Select>
          <Select value={sortKey} onChange={(e) => setSortKey(e.target.value)} className="py-2 px-3 rounded-lg border border-[#DADADA] text-sm text-[#666666]">
            <option value="nome">Ordenar: Nome</option>
            <option value="rm">Ordenar: RM</option>
            <option value="curso">Ordenar: Curso</option>
          </Select>
        </div>
        {editable && (
          <button onClick={() => { setSelected(null); setModal("add"); }} className="flex items-center gap-1.5 px-4 py-2 rounded-lg bg-[#B20000] hover:bg-[#7E0000] text-white text-sm font-medium">
            <Plus size={16} /> Novo Aluno
          </button>
        )}
      </div>

      <DataTable columns={columns} rows={rows} loading={loading} rowKey="rm" emptyTitle="Nenhum aluno encontrado" emptyMessage="Tente ajustar a busca ou os filtros aplicados." />

      {(modal === "add" || modal === "edit") && (
        <AlunoFormModal
          ctx={ctx}
          aluno={selected}
          onClose={() => setModal(null)}
        />
      )}
      {modal === "view" && selected && (
        <AlunoViewModal ctx={ctx} aluno={selected} onClose={() => setModal(null)} />
      )}
    </div>
  );
}

function AlunoFormModal({ ctx, aluno, onClose }) {
  const { alunos, setAlunos, responsaveis, setResponsavelAluno, respIdsDe, addToast } = ctx;
  const isEdit = !!aluno;
  const [form, setForm] = useState(
    aluno || { rm: "", nome: "", ano: ANOS[0], curso: CURSOS[0], periodo: PERIODOS[0] }
  );
  // responsáveis vinculados (N:N): tabela intermediária responsavel_aluno
  const [respSel, setRespSel] = useState(aluno ? respIdsDe(aluno.rm) : []);
  const [errors, setErrors] = useState({});

  function validate() {
    const e = {};
    if (!form.rm.trim()) e.rm = "Informe o RM do aluno.";
    else if (!isEdit && alunos.some((a) => a.rm === form.rm.trim())) e.rm = "Já existe um aluno cadastrado com este RM.";
    if (!form.nome.trim()) e.nome = "Informe o nome completo.";
    if (respSel.length === 0) e.responsaveis = "Selecione ao menos um responsável.";
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  function submit() {
    if (!validate()) return;
    const rm = isEdit ? aluno.rm : form.rm.trim();
    // TODO(API): PUT API_ROTAS.vinculosResponsavelAluno com { responsaveis: respSel } (tabela responsavel_aluno)
    setResponsavelAluno((prev) => [...prev.filter((v) => v.alunoRm !== rm), ...respSel.map((id) => ({ alunoRm: rm, responsavelId: id }))]);
    if (isEdit) {
      setAlunos((prev) => prev.map((a) => (a.rm === aluno.rm ? { ...form } : a)));
      addToast("Dados do aluno atualizados com sucesso.", "success");
    } else {
      setAlunos((prev) => [...prev, { ...form, rm }]);
      addToast("Aluno cadastrado com sucesso.", "success");
    }
    onClose();
  }

  return (
    <Modal
      title={isEdit ? "Editar Aluno" : "Cadastrar Aluno"}
      onClose={onClose}
      footer={
        <>
          <button onClick={onClose} className="px-4 py-2 rounded-lg text-sm font-medium text-[#666666] hover:bg-[#E6E6E6]">Cancelar</button>
          <button onClick={submit} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#B20000] hover:bg-[#7E0000]">Salvar</button>
        </>
      }
    >
      <div className="grid grid-cols-2 gap-x-4">
        <Field label="RM" required error={errors.rm}>
          <TextInput value={form.rm} disabled={isEdit} onChange={(e) => setForm({ ...form, rm: e.target.value.replace(/\D/g, "") })} placeholder="20250001" error={errors.rm} />
        </Field>
        <div className="col-span-2">
          <Field label="Nome completo" required error={errors.nome}>
            <TextInput value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })} placeholder="Nome completo do aluno" error={errors.nome} />
          </Field>
        </div>
        <Field label="Ano">
          <Select value={form.ano} onChange={(e) => setForm({ ...form, ano: e.target.value })}>
            {ANOS.map((a) => <option key={a}>{a}</option>)}
          </Select>
        </Field>
        <Field label="Período">
          <Select value={form.periodo} onChange={(e) => setForm({ ...form, periodo: e.target.value })}>
            {PERIODOS.map((p) => <option key={p}>{p}</option>)}
          </Select>
        </Field>
        <div className="col-span-2">
          <Field label="Curso">
            <Select value={form.curso} onChange={(e) => setForm({ ...form, curso: e.target.value })}>
              {CURSOS.map((c) => <option key={c}>{c}</option>)}
            </Select>
          </Field>
        </div>
        <div className="col-span-2">
          <Field label={`Responsáveis (${respSel.length} selecionado${respSel.length === 1 ? "" : "s"})`} required error={errors.responsaveis}>
            <MultiPick opcoes={responsaveis.map((r) => ({ id: r.id, nome: r.nome }))} valor={respSel} onChange={setRespSel} error={errors.responsaveis} />
          </Field>
        </div>
      </div>
    </Modal>
  );
}

function AlunoViewModal({ ctx, aluno, onClose }) {
  const { responsaveis, atendimentos, orientadores } = ctx;
  const historico = atendimentos.filter((a) => a.alunoRm === aluno.rm).sort((a, b) => (a.data < b.data ? 1 : -1));
  return (
    <Modal title="Dados do Aluno" onClose={onClose} size="lg">
      <div className="grid grid-cols-3 gap-4 mb-5">
        <InfoItem label="RM" value={aluno.rm} icon={Hash} />
