    return () => clearTimeout(t);
  }, [search]);

  const rows = responsaveis.filter((r) => !search || r.nome.toLowerCase().includes(search.toLowerCase()) || r.cpf.includes(search));

  const columns = [
    { key: "id", label: "ID" },
    { key: "nome", label: "Nome" },
    { key: "cpf", label: "CPF" },
    { key: "email", label: "E-mail" },
    { key: "telefone", label: "Telefone" },
    { key: "alunos", label: "Alunos vinculados", render: (r) => ctx.alunosDoResp(r.id).length },
