      key: "acoes", label: "Ações", render: (r) => (
        <div className="flex items-center gap-0.5">
          <IconBtn icon={Eye} title="Consultar" onClick={() => { setSelected(r); setModal("view"); }} />
          <IconBtn icon={Pencil} title="Editar" onClick={() => { setSelected(r); setModal("edit"); }} />
          <IconBtn icon={Trash2} title="Excluir" tone="danger" onClick={() =>
            askConfirm({
              title: "Excluir responsável",
              message: `Tem certeza de que deseja excluir "${r.nome}"? Esta ação não poderá ser desfeita.`,
              danger: true, confirmLabel: "Excluir",
              onConfirm: () => {
                const orfaos = ctx.alunosDoResp(r.id).filter((a) => ctx.respIdsDe(a.rm).length === 1);
                if (orfaos.length) { addToast(`Não é possível excluir: ${orfaos.map((a) => a.nome).join(", ")} ficaria sem responsável. Vincule outro responsável antes.`, "error"); return; }
                setResponsaveis((prev) => prev.filter((x) => x.id !== r.id));
                ctx.setResponsavelAluno((prev) => prev.filter((v) => v.responsavelId !== r.id));
                addToast("Responsável excluído com sucesso.", "success");
              },
            })
          } />
