          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar por nome ou CPF..." className="pl-9 pr-3 py-2 rounded-lg border border-[#DADADA] text-sm w-72 focus:outline-none focus:ring-2 focus:ring-[#B20000]/40" />
        </div>
        <button onClick={() => { setSelected(null); setModal("add"); }} className="flex items-center gap-1.5 px-4 py-2 rounded-lg bg-[#B20000] hover:bg-[#7E0000] text-white text-sm font-medium">
          <Plus size={16} /> Novo Responsável
        </button>
      </div>
      <DataTable columns={columns} rows={rows} loading={loading} emptyTitle="Nenhum responsável encontrado" />
      {(modal === "add" || modal === "edit") && <ResponsavelFormModal ctx={ctx} responsavel={selected} onClose={() => setModal(null)} />}
      {modal === "view" && selected && (
        <Modal title="Dados do Responsável" onClose={() => setModal(null)}>
          <div className="grid grid-cols-2 gap-4">
            <InfoItem icon={User} label="Nome" value={selected.nome} />
            <InfoItem icon={CreditCard} label="CPF" value={selected.cpf} />
            <InfoItem icon={Mail} label="E-mail" value={selected.email} />
            <InfoItem icon={Phone} label="Telefone" value={selected.telefone} />
