          </div>
        </Modal>
      )}
    </div>
  );
}

function ResponsavelFormModal({ ctx, responsavel, onClose }) {
  const { responsaveis, setResponsaveis, addToast } = ctx;
  const isEdit = !!responsavel;
  const [form, setForm] = useState(responsavel || { nome: "", cpf: "", email: "", telefone: "", senha: "" });
  const [errors, setErrors] = useState({});

  function validate() {
    const e = {};
    if (!form.nome.trim()) e.nome = "Informe o nome completo.";
    if (!isValidCPF(form.cpf)) e.cpf = "CPF inválido. Informe os 11 dígitos.";
    if (!isValidEmail(form.email)) e.email = "Informe um e-mail válido.";
    else if (responsaveis.some((r) => r.email === form.email && r.id !== responsavel?.id)) e.email = "Este e-mail já está cadastrado.";
    if (!isEdit && form.senha.length < 6) e.senha = "A senha deve ter ao menos 6 caracteres.";
    setErrors(e);
    return Object.keys(e).length === 0;
  }
  function submit() {
    if (!validate()) return;
    if (isEdit) {
      setResponsaveis((prev) => prev.map((r) => (r.id === responsavel.id ? { ...form } : r)));
      addToast("Responsável atualizado com sucesso.", "success");
    } else {
      setResponsaveis((prev) => [...prev, { ...form, id: uid("R") }]);
      addToast("Responsável cadastrado com sucesso.", "success");
    }
    onClose();
  }
  return (
    <Modal title={isEdit ? "Editar Responsável" : "Cadastrar Responsável"} onClose={onClose}
      footer={<>
        <button onClick={onClose} className="px-4 py-2 rounded-lg text-sm font-medium text-[#666666] hover:bg-[#E6E6E6]">Cancelar</button>
        <button onClick={submit} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#B20000] hover:bg-[#7E0000]">Salvar</button>
      </>}>
      <Field label="Nome completo" required error={errors.nome}><TextInput value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })} error={errors.nome} /></Field>
      <div className="grid grid-cols-2 gap-x-4">
        <Field label="CPF" required error={errors.cpf}><TextInput value={form.cpf} onChange={(e) => setForm({ ...form, cpf: maskCPF(e.target.value) })} placeholder="000.000.000-00" error={errors.cpf} /></Field>
        <Field label="Telefone"><TextInput value={form.telefone} onChange={(e) => setForm({ ...form, telefone: maskPhone(e.target.value) })} placeholder="(11) 90000-0000" /></Field>
      </div>
      <Field label="E-mail" required error={errors.email}><TextInput type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} error={errors.email} /></Field>
      {!isEdit && <Field label="Senha" required error={errors.senha}><TextInput type="password" value={form.senha} onChange={(e) => setForm({ ...form, senha: e.target.value })} error={errors.senha} /></Field>}
    </Modal>
  );
}

