/* ============================================================
   AGENDAMENTOS (Calendário)
   ============================================================ */
function AgendamentosPage({ ctx, scope }) {
  const { atendimentos, setAtendimentos, reunioes, alunos, orientadores, addToast, askConfirm, currentUserId, role, setPage } = ctx;
  const [view, setView] = useState("mensal");
  const [ref, setRef] = useState(new Date(TODAY));
  const [selectedDay, setSelectedDay] = useState(dateKey(TODAY));
  const [detail, setDetail] = useState(null);
  const [novo, setNovo] = useState(false);
  const scoped = (scope === "mine" ? atendimentos.filter(a => a.orientadorId === currentUserId) : atendimentos).filter(a => !["Cancelado", "Recusado"].includes(a.status));
  const scopedMeetings = reunioes.filter(r => r.status !== "Cancelada" && (role === "instituicao" || r.criadoPor === currentUserId || (r.participantes || []).includes(currentUserId)));
  const monthStart = new Date(ref.getFullYear(), ref.getMonth(), 1);
  const cells = [];
  for (let i=0;i<monthStart.getDay();i++) cells.push(null);
  for (let d=1;d<=new Date(ref.getFullYear(),ref.getMonth()+1,0).getDate();d++) cells.push(new Date(ref.getFullYear(),ref.getMonth(),d));
  function eventosNaData(data) {
    return [
      ...scoped.filter(a => a.data === data).map(a => ({...a,tipo:"atendimento",inicio:a.horario,fim:fimAtendimento(a)})),
      ...scopedMeetings.filter(r => r.data === data).map(r => ({...r,tipo:"reuniao",inicio:r.horario,fim:r.horarioFim || r.horario}))
    ].sort((a,b)=>(a.inicio).localeCompare(b.inicio));
  }
  function rangeList() {
    let de, ate;
    if (view === "diaria") de=ate=selectedDay;
    else if (view === "semanal") { const base=parseDay(selectedDay), dow=base.getDay(); de=dateKey(addDays(base,-dow)); ate=dateKey(addDays(base,6-dow)); }
    else { de=dateKey(monthStart).slice(0,7)+"-01"; ate=dateKey(new Date(ref.getFullYear(),ref.getMonth()+1,0)); }
    const dias = [...new Set([...scoped.map(a=>a.data),...scopedMeetings.map(r=>r.data)])].filter(d=>d>=de&&d<=ate);
    return dias.flatMap(eventosNaData).sort((a,b)=>(a.data+a.inicio).localeCompare(b.data+b.inicio));
  }
  function cancelar(item) {
    askConfirm({ title:"Cancelar agendamento", message:`Deseja realmente cancelar o agendamento de ${alunoNome(alunos,item.alunoRm)} em ${formatDate(item.data)}?`, danger:true, confirmLabel:"Cancelar agendamento", onConfirm:()=>{setAtendimentos(prev=>prev.map(a=>a.id===item.id?{...a,status:"Cancelado"}:a));addToast("Agendamento cancelado.","success");setDetail(null);} });
  }
  function confirmar(item) {
    if (foraDisponibilidade(ctx.disponibilidades, item)) return addToast("O horário solicitado está fora da disponibilidade cadastrada do orientador.", "error");
    const ini=toMin(item.horario), fim=ini+DURACAO_ATENDIMENTO;
    const responsaveisDoAluno=ctx.respIdsDe(item.alunoRm);
    const conflito=conflitoDeCompromisso({pessoaIds:[item.orientadorId,...responsaveisDoAluno],data:item.data,inicio:ini,fim,atendimentos,reunioes,ignorarAtendimento:item.id});
    if (reuniaoAtivaNoDia(reunioes,item.data)) return addToast("Há uma reunião nesta data. O dia inteiro está bloqueado para atendimentos.","error");
    if (conflito) return addToast(conflito,"error");
    setAtendimentos(prev=>prev.map(a=>a.id===item.id?{...a,status:"Confirmado"}:a)); addToast("Atendimento confirmado com sucesso.","success"); setDetail(null);
  }
  const list=rangeList();
  return <div className="space-y-4">
    <div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><button onClick={()=>setRef(new Date(ref.getFullYear(),ref.getMonth()-1,1))} className="p-2 rounded-lg border border-[#DADADA] hover:bg-[#F8F8F8]"><ChevronLeft size={16}/></button><p className="font-medium text-gray-700 w-40 text-center capitalize">{ref.toLocaleDateString("pt-BR",{month:"long",year:"numeric"})}</p><button onClick={()=>setRef(new Date(ref.getFullYear(),ref.getMonth()+1,1))} className="p-2 rounded-lg border border-[#DADADA] hover:bg-[#F8F8F8]"><ChevronRight size={16}/></button></div>
      <div className="flex flex-wrap items-center gap-2"><button onClick={()=>setNovo(true)} className="px-4 py-2 rounded-lg bg-[#B20000] hover:bg-[#7E0000] text-white text-sm font-medium flex items-center gap-1.5"><Plus size={16}/> Novo atendimento</button><button onClick={()=>{ sessionStorage.setItem("sigepAbrirNovaReuniao", "1"); setPage("reunioes"); }} className="px-4 py-2 rounded-lg border border-purple-200 bg-purple-50 text-purple-800 text-sm font-medium flex items-center gap-1.5"><Plus size={16}/> Nova reunião</button><div className="flex items-center gap-1 bg-[#E6E6E6] rounded-lg p-1">{["mensal","semanal","diaria"].map(v=><button key={v} onClick={()=>setView(v)} className={`px-3 py-1.5 rounded-md text-sm capitalize font-medium ${view===v?"bg-white shadow-sm text-[#B20000]":"text-[#666666]"}`}>{v}</button>)}</div></div>
    </div>
    <div className="grid lg:grid-cols-3 gap-4"><div className="lg:col-span-2 bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-4"><div className="grid grid-cols-7 gap-1 mb-1">{["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].map(d=><div key={d} className="text-center text-xs font-medium text-gray-400 py-1">{d}</div>)}</div>
      <div className="grid grid-cols-7 gap-1">{cells.map((d,i)=>{if(!d)return <div key={i}/>;const evs=eventosNaData(dateKey(d));const selected=dateKey(d)===selectedDay;const today=dateKey(d)===dateKey(TODAY);return <button key={i} onClick={()=>setSelectedDay(dateKey(d))} className={`aspect-square rounded-lg border p-1.5 flex flex-col items-start text-left ${selected?"border-[#B20000] bg-[#B20000]/10":"border-[#E6E6E6] hover:bg-[#F8F8F8]"}`}><span className={`text-xs w-5 h-5 rounded-full flex items-center justify-center ${today?"bg-[#7E0000] text-white":"text-[#666666]"}`}>{d.getDate()}</span><div className="flex flex-wrap gap-0.5 mt-1">{evs.slice(0,5).map((e,j)=><span key={j} title={e.tipo==="reuniao"?"Reunião":e.status} className={`w-1.5 h-1.5 rounded-full ${e.tipo==="reuniao"?"bg-[#8A29E6]":e.status==="Finalizado"?"bg-[#A0C340]":e.status==="Pendente"?"hidden":e.status==="Em Andamento"?"bg-[#F59E0B]":"bg-[#4C7EFF]"}`}/>)}</div></button>})}</div>
      <div className="flex flex-wrap gap-x-4 gap-y-2 mt-3 text-xs text-[#666666]">
        <span><i className="inline-block w-2 h-2 rounded-full bg-[#4C7EFF] mr-1"/>Confirmado</span>
        <span><i className="inline-block w-2 h-2 rounded-full bg-[#F59E0B] mr-1"/>Em andamento</span>
        <span><i className="inline-block w-2 h-2 rounded-full bg-[#A0C340] mr-1"/>Finalizado</span>
        <span><i className="inline-block w-2 h-2 rounded-full bg-[#8A29E6] mr-1"/>Reunião</span>
      </div></div>
      <div className="bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-4"><p className="font-medium text-gray-700 mb-3 text-sm">{view==="diaria"?`Agenda de ${formatDate(selectedDay)}`:view==="semanal"?"Agenda da semana":`Agenda de ${ref.toLocaleDateString("pt-BR",{month:"long",year:"numeric"})}`}</p><div className="space-y-2 max-h-[26.25rem] overflow-y-auto">{list.length===0&&<EmptyState title="Sem compromissos" message="Não há atendimentos ou reuniões para este período."/>}{list.map(item=>item.tipo==="reuniao"?<button key={`r-${item.id}`} onClick={()=>setDetail(item)} className="w-full text-left border border-purple-200 bg-purple-50/40 rounded-lg p-3"><div className="flex items-center justify-between mb-1"><span className="text-xs font-medium text-[#666666]">{formatDate(item.data)} · {item.inicio}–{item.fim}</span><span className="text-xs rounded-full px-2 py-1 bg-purple-100 text-purple-800">Reunião</span></div><p className="text-sm text-gray-700 font-medium">{item.assunto}</p></button>:<button key={`a-${item.id}`} onClick={()=>setDetail(item)} className="w-full text-left border border-[#E6E6E6] rounded-lg p-3 hover:border-[#B20000]/50 hover:bg-[#B20000]/5"><div className="flex items-center justify-between mb-1"><span className="text-xs font-medium text-[#666666]">{formatDate(item.data)} · {item.inicio}–{item.fim}</span><Badge status={item.status}/></div><p className="text-sm text-gray-700 font-medium">{alunoNome(alunos,item.alunoRm)}</p><p className="text-xs text-gray-400">{orientadorNome(orientadores,item.orientadorId)} · {item.motivo}</p></button>)}</div></div></div>
    {novo&&<NovoAtendimentoModal ctx={ctx} scope={scope} dataInicial={selectedDay} onClose={()=>setNovo(false)}/>}
    {detail&&<Modal title={detail.tipo==="reuniao"?detail.assunto:"Detalhes do Agendamento"} onClose={()=>setDetail(null)}>{detail.tipo==="reuniao"?<><div className="grid grid-cols-2 gap-4"><InfoItem icon={Calendar} label="Data" value={formatDate(detail.data)}/><InfoItem icon={Clock} label="Horário" value={`${detail.inicio}–${detail.fim}`}/><InfoItem icon={Info} label="Tipo" value="Reunião"/></div>{detail.descricao&&<p className="text-sm text-gray-700 mt-3">{detail.descricao}</p>}</>:<><div className="grid grid-cols-2 gap-4 mb-4"><InfoItem icon={GraduationCap} label="Aluno" value={alunoNome(alunos,detail.alunoRm)}/><InfoItem icon={Hash} label="RM" value={detail.alunoRm}/><InfoItem icon={UserCheck} label="Orientador" value={orientadorNome(orientadores,detail.orientadorId)}/><InfoItem icon={Calendar} label="Data" value={formatDate(detail.data)}/><InfoItem icon={Clock} label="Horário" value={`${detail.inicio}–${detail.fim}`}/><InfoItem icon={FileText} label="Motivo" value={detail.motivo}/><InfoItem icon={Info} label="Status" value={<Badge status={detail.status}/>}/></div>{["Pendente","Confirmado"].includes(detail.status)&&<div className="flex justify-end gap-2 pt-3 border-t border-[#E6E6E6]">{detail.status==="Pendente"&&<button onClick={()=>confirmar(detail)} className="px-4 py-2 rounded-lg text-sm font-medium text-[#1F2A05] bg-[#A0C340] hover:bg-[#8FB033]"><Check size={15}/> Confirmar</button>}<button onClick={()=>cancelar(detail)} className="px-4 py-2 rounded-lg text-sm font-medium text-[#B20000] border border-[#FF4C4D]/30"><Ban size={15}/> Cancelar</button></div>}</>}</Modal>}
  </div>;
}

/* ============================================================
   ATENDIMENTOS
   ============================================================ */
function AtendimentosPage({ ctx, scope }) {
  const { atendimentos, setAtendimentos, alunos, orientadores, currentUserId, disponibilidades, reunioes, responsaveis, addToast } = ctx;
  const [search, setSearch] = useState("");
  const [dataFiltro, setDataFiltro] = useState("");
  const [orientadorFiltro, setOrientadorFiltro] = useState("");
  const [cursoFiltro, setCursoFiltro] = useState("");
  const [statusFiltro, setStatusFiltro] = useState("");
  const [detail, setDetail] = useState(null);
  const [registerId, setRegisterId] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    setLoading(true);
    const t = setTimeout(() => setLoading(false), 350);
    return () => clearTimeout(t);
  }, [search, dataFiltro, orientadorFiltro, cursoFiltro, statusFiltro]);

  const scoped = (scope === "mine" ? atendimentos.filter((a) => a.orientadorId === currentUserId) : atendimentos)
    .filter((a) => !(a.status === "Pendente" && foraDisponibilidade(disponibilidades, a)));

  function aprovarAtendimento(a) {
    if (foraDisponibilidade(disponibilidades, a)) return addToast("Solicitação removida: o horário está fora da disponibilidade do orientador.", "error");
    if (reuniaoAtivaNoDia(reunioes, a.data)) return addToast("Há uma reunião nesta data. O dia inteiro está bloqueado para atendimentos.", "error");
    const responsaveisDoAluno = ctx.respIdsDe(a.alunoRm);
    const conflito = conflitoDeCompromisso({ pessoaIds: [a.orientadorId, ...responsaveisDoAluno], data: a.data, inicio: toMin(a.horario), fim: toMin(a.horario) + DURACAO_ATENDIMENTO, atendimentos, reunioes, ignorarAtendimento: a.id });
    if (conflito) return addToast(conflito, "error");
    const conflitoAluno = atendimentos.some((b) => b.id !== a.id && b.alunoRm === a.alunoRm && b.data === a.data && ATIVOS.includes(b.status) && intervalosSeSobrepoem(toMin(a.horario), toMin(a.horario) + DURACAO_ATENDIMENTO, toMin(b.horario), toMin(b.horario) + DURACAO_ATENDIMENTO));
    if (conflitoAluno) return addToast("O aluno já possui outro atendimento neste intervalo.", "error");
    setAtendimentos((prev) => prev.map((x) => x.id === a.id ? { ...x, status: "Confirmado" } : x));
    addToast("Atendimento confirmado com sucesso.", "success");
  }

  const rows = scoped.filter((a) => {
    const aluno = alunos.find((x) => x.rm === a.alunoRm);
    const matchSearch = !search || (aluno && aluno.nome.toLowerCase().includes(search.toLowerCase())) || a.alunoRm.includes(search);
    const matchData = !dataFiltro || a.data === dataFiltro;
    const matchOrientador = !orientadorFiltro || a.orientadorId === orientadorFiltro;
    const matchCurso = !cursoFiltro || (aluno && aluno.curso === cursoFiltro);
    const matchStatus = !statusFiltro || a.status === statusFiltro;
    return matchSearch && matchData && matchOrientador && matchCurso && matchStatus;
  }).sort((a, b) => (a.data < b.data ? 1 : -1));

  const columns = [
    { key: "id", label: "ID" },
    { key: "aluno", label: "Aluno", render: (a) => alunoNome(alunos, a.alunoRm) },
    { key: "alunoRm", label: "RM" },
    { key: "responsavel", label: "Responsáveis", render: (a) => ctx.nomesRespDe(a.alunoRm) },
    { key: "orientador", label: "Orientador", render: (a) => orientadorNome(orientadores, a.orientadorId) },
    { key: "data", label: "Data", render: (a) => formatDate(a.data) },
    { key: "horario", label: "Horário" },
    { key: "motivo", label: "Motivo" },
    { key: "status", label: "Status", render: (a) => <Badge status={a.status} /> },
    {
      key: "acoes", label: "Ações", render: (a) => (
        <div className="flex items-center gap-0.5">
          <IconBtn icon={Eye} title="Detalhes" onClick={() => setDetail(a)} />
          {scope === "mine" && a.status === "Pendente" && (
            <IconBtn icon={Check} title="Aceitar atendimento" onClick={() => aprovarAtendimento(a)} />
          )}
          {scope === "mine" && ["Confirmado", "Em Andamento"].includes(a.status) && (
            <IconBtn icon={PlayCircle} title={a.status === "Confirmado" ? "Iniciar atendimento" : "Registrar sessão"} onClick={() => setRegisterId(a.id)} />
          )}
        </div>
      ),
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar aluno ou RM..." className="pl-9 pr-3 py-2 rounded-lg border border-[#DADADA] text-sm w-56 focus:outline-none focus:ring-2 focus:ring-[#B20000]/40" />
        </div>
        <input type="date" value={dataFiltro} onChange={(e) => setDataFiltro(e.target.value)} className="py-2 px-3 rounded-lg border border-[#DADADA] text-sm text-[#666666]" />
        {scope !== "mine" && (
          <Select busca value={orientadorFiltro} onChange={(e) => setOrientadorFiltro(e.target.value)} className="py-2 px-3 rounded-lg border border-[#DADADA] text-sm text-[#666666]">
            <option value="">Todos os orientadores</option>
            {orientadores.map((o) => <option key={o.id} value={o.id}>{o.nome}</option>)}
          </Select>
        )}
        <Select value={cursoFiltro} onChange={(e) => setCursoFiltro(e.target.value)} className="py-2 px-3 rounded-lg border border-[#DADADA] text-sm text-[#666666]">
          <option value="">Todos os cursos</option>
          {CURSOS.map((c) => <option key={c} value={c}>{c}</option>)}
        </Select>
        <Select value={statusFiltro} onChange={(e) => setStatusFiltro(e.target.value)} className="py-2 px-3 rounded-lg border border-[#DADADA] text-sm text-[#666666]">
          <option value="">Todos os status</option>
          {["Pendente", "Confirmado", "Em Andamento", "Finalizado", "Cancelado"].map((s) => <option key={s}>{s}</option>)}
        </Select>
      </div>

      <DataTable columns={columns} rows={rows} loading={loading} emptyTitle="Nenhum atendimento encontrado" />

      {detail && <AtendimentoDetailModal ctx={ctx} item={detail} onClose={() => setDetail(null)} />}
      {registerId && <RegistrarAtendimentoModal ctx={ctx} id={registerId} onClose={() => setRegisterId(null)} />}
    </div>
  );
}

function AtendimentoDetailModal({ ctx, item, onClose }) {
  const { alunos, orientadores, responsaveis } = ctx;
  const aluno = alunos.find((a) => a.rm === item.alunoRm);
  return (
    <Modal title={`Atendimento ${item.id}`} onClose={onClose} size="lg">
      <div className="grid grid-cols-2 gap-4 mb-5">
        <InfoItem icon={GraduationCap} label="Aluno" value={item.alunoRm ? alunoNome(alunos, item.alunoRm) : "—"} />
        <InfoItem icon={Hash} label="RM" value={item.alunoRm} />
        <InfoItem icon={BookOpen} label="Curso" value={aluno?.curso} />
        <InfoItem icon={UserCheck} label="Orientador" value={orientadorNome(orientadores, item.orientadorId)} />
        <InfoItem icon={Calendar} label="Data" value={formatDate(item.data)} />
        <InfoItem icon={Clock} label="Horário" value={item.horario} />
        <InfoItem icon={Info} label="Status" value={<Badge status={item.status} />} />
      </div>
      <div className="space-y-3 border-t border-[#E6E6E6] pt-4">
        <div><p className="text-xs text-gray-400 mb-1">Motivo</p><p className="text-sm text-gray-700">{item.motivo}</p></div>
        <div><p className="text-xs text-gray-400 mb-1">Descrição</p><p className="text-sm text-gray-700">{item.descricao || "Nenhuma descrição registrada."}</p></div>
        <div><p className="text-xs text-gray-400 mb-1">Observações</p><p className="text-sm text-gray-700">{item.observacoes || "Nenhuma observação registrada."}</p></div>
        <div><p className="text-xs text-gray-400 mb-1">Resultado</p><p className="text-sm text-gray-700">{item.resultado || "Atendimento ainda não finalizado."}</p></div>
        <div><p className="text-xs text-gray-400 mb-2">Sessões registradas ({(item.sessoes || []).length})</p>{(item.sessoes || []).length ? <ol className="space-y-2">{item.sessoes.map((sessao,i)=><li key={sessao.id || i} className="rounded-lg border border-[#E6E6E6] p-3"><p className="text-xs font-semibold text-gray-700">Sessão {i+1} · {formatDate(sessao.data)} {sessao.horario ? `· ${sessao.horario}` : ""}</p>{sessao.descricao && <p className="text-sm text-gray-600 mt-1 whitespace-pre-wrap break-words">{sessao.descricao}</p>}</li>)}</ol> : <p className="text-sm text-gray-500">Nenhuma sessão adicional registrada.</p>}</div>
      </div>
    </Modal>
  );
}

function RegistrarAtendimentoModal({ ctx, id, onClose }) {
  const { atendimentos, setAtendimentos, alunos, addToast, askConfirm } = ctx;
  const item = atendimentos.find((a) => a.id === id);
  const aluno = alunos.find((a) => a.rm === item.alunoRm);
  const [descricao, setDescricao] = useState(item.descricao || "");
  const [observacoes, setObservacoes] = useState(item.observacoes || "");
  const [resultado, setResultado] = useState(item.resultado || "");
  const [status, setStatus] = useState(item.status);
  const [dataSessao, setDataSessao] = useState(dateKey(TODAY));
  const [horaSessao, setHoraSessao] = useState(new Date().toTimeString().slice(0,5));

  function update(fields, toastMsg) {
    setAtendimentos((prev) => prev.map((a) => (a.id === id ? { ...a, ...fields } : a)));
    if (toastMsg) addToast(toastMsg, "success");
  }
  function iniciar() {
    if (item.status !== "Confirmado") return addToast("Somente atendimentos confirmados podem ser iniciados.", "error");
    if (!dataSessao) return addToast("Informe a data da sessão.", "error");
    const sessao = { id: uid("S"), data: dataSessao, horario: horaSessao, descricao, observacoes };
    setStatus("Em Andamento");
    update({ status: "Em Andamento", descricao, observacoes, sessoes: [...(item.sessoes || []), sessao] }, "Atendimento iniciado. Você poderá registrar novas sessões e encerrá-lo depois.");
  }
  function registrarSessao() {
    if (!dataSessao) return addToast("Informe a data da próxima sessão.", "error");
    const sessoes = [...(item.sessoes || []), { id: uid("S"), data: dataSessao, horario: horaSessao, descricao, observacoes }];
    update({ status: "Em Andamento", descricao, observacoes, sessoes }, "Nova sessão registrada. O atendimento continua em andamento.");
  }
  function salvar() { update({ descricao, observacoes, resultado }, "Registro salvo."); }
  function finalizar() {
    if (!descricao.trim() || !resultado.trim()) { addToast("Preencha a descrição e o resultado antes de finalizar o atendimento.", "error"); return; }
    update({ status: "Finalizado", descricao, observacoes, resultado, encerradoEm: new Date().toISOString() }, "Atendimento finalizado e registrado no histórico do aluno.");
    onClose();
  }
  function cancelar() {
    askConfirm({ title: "Cancelar atendimento", message: "Tem certeza de que deseja cancelar este atendimento?", danger: true, confirmLabel: "Cancelar atendimento", onConfirm: () => { update({ status: "Cancelado" }, "Atendimento cancelado."); onClose(); } });
  }
  return (
    <Modal title="Registro de Atendimento" onClose={onClose} size="lg">
      <div className="grid grid-cols-2 gap-4 mb-4"><InfoItem icon={GraduationCap} label="Aluno" value={aluno?.nome}/><InfoItem icon={Hash} label="RM" value={item.alunoRm}/><InfoItem icon={BookOpen} label="Curso" value={aluno?.curso}/><InfoItem icon={Calendar} label="Data inicial" value={formatDate(item.data)}/><InfoItem icon={Clock} label="Horário" value={item.horario}/><InfoItem icon={FileText} label="Motivo" value={item.motivo}/><InfoItem icon={Info} label="Status" value={<Badge status={status}/>}/></div>
      <div className="rounded-lg border border-[#E6E6E6] p-3 mb-4"><p className="font-semibold text-sm text-gray-800 mb-2">Sessões do atendimento ({(item.sessoes || []).length})</p>{(item.sessoes || []).length ? <ol className="space-y-2">{item.sessoes.map((x,i)=><li key={x.id || i} className="text-sm text-gray-600">Sessão {i+1}: {formatDate(x.data)} {x.horario ? `às ${x.horario}` : ""}{x.descricao ? ` — ${x.descricao}` : ""}</li>)}</ol> : <p className="text-xs text-gray-500">A primeira sessão será registrada ao iniciar o atendimento.</p>}</div>
      {status !== "Finalizado" && status !== "Cancelado" && <div className="grid grid-cols-2 gap-3"><Field label="Data da sessão" required><input type="date" className={inputCls()} value={dataSessao} onChange={e=>setDataSessao(e.target.value)}/></Field><Field label="Horário da sessão"><input type="time" className={inputCls()} value={horaSessao} onChange={e=>setHoraSessao(e.target.value)}/></Field></div>}
      <Field label="Descrição / registro desta sessão"><TextArea value={descricao} onChange={e=>setDescricao(e.target.value)} placeholder="Descreva o que foi tratado nesta sessão..."/></Field>
      <Field label="Observações"><TextArea value={observacoes} onChange={e=>setObservacoes(e.target.value)} placeholder="Observações adicionais..."/></Field>
      <Field label="Resultado / encaminhamentos para encerramento"><TextArea value={resultado} onChange={e=>setResultado(e.target.value)} placeholder="Preencha quando decidir encerrar o atendimento..."/></Field>
      <div className="flex flex-wrap justify-end gap-2 pt-3 border-t border-[#E6E6E6]">
        <button onClick={cancelar} className="px-4 py-2 rounded-lg text-sm font-medium text-[#B20000] border border-[#FF4C4D]/30 hover:bg-[#FF4C4D]/10">Cancelar atendimento</button>
        {status === "Confirmado" && <button onClick={iniciar} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#7E0000] hover:bg-[#B20000] flex items-center gap-1.5"><PlayCircle size={15}/> Iniciar atendimento</button>}
        {status === "Em Andamento" && <button onClick={registrarSessao} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#7E0000] hover:bg-[#B20000] flex items-center gap-1.5"><Plus size={15}/> Registrar próxima sessão</button>}
        <button onClick={salvar} className="px-4 py-2 rounded-lg text-sm font-medium text-gray-700 border border-[#DADADA] hover:bg-[#F8F8F8] flex items-center gap-1.5"><Save size={15}/> Salvar sem encerrar</button>
        {status === "Em Andamento" && <button onClick={finalizar} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#B20000] hover:bg-[#7E0000] flex items-center gap-1.5"><CheckCircle2 size={15}/> Encerrar atendimento</button>}
      </div>
      {status === "Em Andamento" && <p className="text-xs text-gray-500 mt-2">O atendimento pode permanecer em andamento por tempo indeterminado. Registre novas sessões quando necessário e encerre somente quando o acompanhamento terminar.</p>}
    </Modal>
  );
}

/* ============================================================
   RELATÓRIOS
   ============================================================ */
function RelatoriosPage({ ctx, scope }) {
  const { atendimentos, alunos, orientadores, currentUserId, addToast } = ctx;
  const [tipo, setTipo] = useState("geral");
  const [dataIni, setDataIni] = useState("");
  const [dataFim, setDataFim] = useState("");
  const [alunoF, setAlunoF] = useState("");
  const [orientadorF, setOrientadorF] = useState(scope === "mine" ? currentUserId : "");
  const [cursoF, setCursoF] = useState("");
  const [anoF, setAnoF] = useState("");
  const [periodoF, setPeriodoF] = useState("");
  const [statusF, setStatusF] = useState("");
  const [gerado, setGerado] = useState(false);

  const scoped = scope === "mine" ? atendimentos.filter((a) => a.orientadorId === currentUserId) : atendimentos;

  const resultado = useMemo(() => {
    return scoped.filter((a) => {
      const aluno = alunos.find((x) => x.rm === a.alunoRm);
      if (dataIni && a.data < dataIni) return false;
      if (dataFim && a.data > dataFim) return false;
      if (alunoF && a.alunoRm !== alunoF) return false;
      if (orientadorF && a.orientadorId !== orientadorF) return false;
      if (cursoF && aluno?.curso !== cursoF) return false;
      if (anoF && aluno?.ano !== anoF) return false;
      if (periodoF && aluno?.periodo !== periodoF) return false;
      if (statusF && a.status !== statusF) return false;
      if (tipo === "cancelamentos" && a.status !== "Cancelado") return false;
      return true;
    });
  }, [scoped, dataIni, dataFim, alunoF, orientadorF, cursoF, anoF, periodoF, statusF, tipo]);

  const porStatus = ["Pendente", "Confirmado", "Em Andamento", "Finalizado", "Cancelado"].map((s) => ({
    status: s, total: resultado.filter((r) => r.status === s).length,
  }));

  function exportarSVG() {
    const width = 1280, rowH = 44, top = 390, height = top + porStatus.length * rowH + 150;
    const max = Math.max(1, ...porStatus.map(x => x.total));
    const esc = (v) => String(v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
    const total = resultado.length;
    const pendentes = resultado.filter(r => r.status === "Pendente").length;
    const finalizados = resultado.filter(r => r.status === "Finalizado").length;
    const cancelados = resultado.filter(r => r.status === "Cancelado").length;
    const cards = [
      {label:"Total de atendimentos", value:total, color:"#334155", bg:"#F1F5F9", icon:"▤"},
      {label:"Pendentes", value:pendentes, color:"#D97706", bg:"#FFF7E6", icon:"◷"},
      {label:"Finalizados", value:finalizados, color:"#16834A", bg:"#EAF7EF", icon:"✓"},
      {label:"Cancelados", value:cancelados, color:"#DC3333", bg:"#FDECEC", icon:"×"}
    ];
    const cardSvg = cards.map((c,i)=>{const x=34+i*304;return `<g><rect x="${x}" y="160" width="286" height="108" rx="18" fill="${c.bg}" stroke="${c.color}" stroke-opacity=".14"/><circle cx="${x+48}" cy="214" r="31" fill="${c.color}"/><text x="${x+48}" y="224" text-anchor="middle" font-family="Arial,sans-serif" font-size="31" font-weight="700" fill="#FFFFFF">${c.icon}</text><text x="${x+92}" y="204" font-family="Arial,sans-serif" font-size="17" fill="#334155">${c.label}</text><text x="${x+92}" y="245" font-family="Arial,sans-serif" font-size="38" font-weight="700" fill="${c.color}">${c.value}</text></g>`}).join("");
    const bars = porStatus.map((x,i) => {
      const y = top + i * rowH, w = Math.max(0, Math.round((x.total/max)*820));
      const fills = {"Pendente":"#F59E0B","Confirmado":"#4C7EFF","Em Andamento":"#F59E0B","Finalizado":"#239653","Cancelado":"#E23B3B"};
      const pct = total ? (x.total/total*100).toFixed(1).replace(".",",") : "0,0";
      return `<g><text x="62" y="${y+25}" font-family="Arial,sans-serif" font-size="18" fill="#172033">${esc(x.status)}</text><rect x="245" y="${y}" width="820" height="28" rx="9" fill="#E9EBEF"/><rect x="245" y="${y}" width="${w}" height="28" rx="9" fill="${fills[x.status] || "#B20000"}"/><text x="1110" y="${y+22}" font-family="Arial,sans-serif" font-size="18" font-weight="700" fill="#172033">${x.total}</text><text x="1185" y="${y+22}" text-anchor="end" font-family="Arial,sans-serif" font-size="16" fill="#46536A">(${pct}%)</text></g>`;
    }).join("");
    const periodo = dataIni || dataFim ? `${dataIni ? formatDate(dataIni) : "Início"} a ${dataFim ? formatDate(dataFim) : "Hoje"}` : "Todos os períodos";
    const resumo = total ? `Foram registrados ${total} atendimentos no período, com predominância de ${pendentes >= finalizados && pendentes >= cancelados ? "solicitações pendentes" : "atendimentos finalizados"}.` : "Nenhum atendimento foi registrado no período selecionado.";
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1280" height="${height}" viewBox="0 0 1280 ${height}"><title>Relatório SIGEP — Atendimentos</title><desc>Resumo de ${total} atendimentos. Período: ${esc(periodo)}.</desc><rect width="1280" height="${height}" fill="#F7F8FA"/><rect x="10" y="10" width="1260" height="${height-20}" rx="22" fill="#FFFFFF" stroke="#D9DEE7" stroke-width="2"/><image x="48" y="30" width="245" height="100" href="${LOGO_SIGEP}" xlink:href="${LOGO_SIGEP}" preserveAspectRatio="xMidYMid meet"/><text x="350" y="78" font-family="Arial,sans-serif" font-size="38" font-weight="700" fill="#7E0000">Relatório de atendimentos</text><text x="352" y="116" font-family="Arial,sans-serif" font-size="20" fill="#46536A">▦  Período: ${esc(periodo)}</text><line x1="34" y1="142" x2="1246" y2="142" stroke="#B20000" stroke-opacity=".65" stroke-width="2"/>${cardSvg}<rect x="34" y="292" width="1212" height="${top + porStatus.length*rowH - 278}" rx="18" fill="#FFFFFF" stroke="#E0E4EA"/><path d="M52 292 H1228 Q1246 292 1246 310 V342 H34 V310 Q34 292 52 292Z" fill="#7E0000"/><text x="66" y="326" font-family="Arial,sans-serif" font-size="22" font-weight="700" fill="#FFFFFF">▮  Distribuição dos atendimentos</text>${bars}<rect x="34" y="${height-116}" width="1212" height="82" rx="16" fill="#F5F4F8" stroke="#DED9E8"/><circle cx="78" cy="${height-75}" r="27" fill="#8A101A"/><text x="78" y="${height-65}" text-anchor="middle" font-family="Arial,sans-serif" font-size="32" font-weight="700" fill="#FFFFFF">i</text><text x="120" y="${height-82}" font-family="Arial,sans-serif" font-size="22" font-weight="700" fill="#7E0000">Resumo</text><text x="120" y="${height-52}" font-family="Arial,sans-serif" font-size="15" fill="#172033">${esc(resumo)}</text><line x1="790" y1="${height-98}" x2="790" y2="${height-50}" stroke="#8A101A"/><text x="820" y="${height-80}" font-family="Arial,sans-serif" font-size="14" fill="#263247">▦  Gerado em: ${new Date().toLocaleString("pt-BR")}</text><text x="820" y="${height-55}" font-family="Arial,sans-serif" font-size="14" fill="#263247">SIGEP — Sistema Integrado de Gestão Educacional e Pedagógica</text></svg>`;
    const url = URL.createObjectURL(new Blob([svg], {type:"image/svg+xml;charset=utf-8"})); const a=document.createElement("a"); a.href=url; a.download="relatorio-sigep-atendimentos.svg"; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); addToast("Relatório SVG exportado.","success");
  }

  return (
    <div className="space-y-4 print-area">
      <div className="bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-4 no-print">
        <div className="flex flex-wrap items-center gap-2 mb-3">
          {[
            ["geral", "Geral"], ["aluno", "Por aluno"], ["orientador", "Por orientador"],
            ["curso", "Por curso"], ["periodo", "Por período"], ["cancelamentos", "Cancelamentos"],
          ].map(([key, label]) => (
            <button key={key} onClick={() => setTipo(key)} className={`px-3 py-1.5 rounded-lg text-sm font-medium border ${tipo === key ? "bg-[#7E0000] text-white border-[#7E0000]" : "border-[#DADADA] text-[#666666] hover:bg-[#F8F8F8]"}`}>
              {label}
            </button>
          ))}
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div><label className="text-xs text-[#666666] mb-1 block">Data inicial</label><input type="date" value={dataIni} onChange={(e) => setDataIni(e.target.value)} className="w-full py-2 px-3 rounded-lg border border-[#DADADA] text-sm" /></div>
          <div><label className="text-xs text-[#666666] mb-1 block">Data final</label><input type="date" value={dataFim} onChange={(e) => setDataFim(e.target.value)} className="w-full py-2 px-3 rounded-lg border border-[#DADADA] text-sm" /></div>
          <div><label className="text-xs text-[#666666] mb-1 block">Aluno</label>
            <Select busca value={alunoF} onChange={(e) => setAlunoF(e.target.value)} className="w-full py-2 px-3 rounded-lg border border-[#DADADA] text-sm"><option value="">Todos</option>{alunos.map((a) => <option key={a.rm} value={a.rm}>{a.nome}</option>)}</Select>
          </div>
          {scope !== "mine" && (
            <div><label className="text-xs text-[#666666] mb-1 block">Orientador</label>
              <Select busca value={orientadorF} onChange={(e) => setOrientadorF(e.target.value)} className="w-full py-2 px-3 rounded-lg border border-[#DADADA] text-sm"><option value="">Todos</option>{orientadores.map((o) => <option key={o.id} value={o.id}>{o.nome}</option>)}</Select>
            </div>
          )}
          <div><label className="text-xs text-[#666666] mb-1 block">Curso</label>
            <Select value={cursoF} onChange={(e) => setCursoF(e.target.value)} className="w-full py-2 px-3 rounded-lg border border-[#DADADA] text-sm"><option value="">Todos</option>{CURSOS.map((c) => <option key={c}>{c}</option>)}</Select>
          </div>
          <div><label className="text-xs text-[#666666] mb-1 block">Ano</label>
            <Select value={anoF} onChange={(e) => setAnoF(e.target.value)} className="w-full py-2 px-3 rounded-lg border border-[#DADADA] text-sm"><option value="">Todos</option>{ANOS.map((a) => <option key={a}>{a}</option>)}</Select>
          </div>
          <div><label className="text-xs text-[#666666] mb-1 block">Período</label>
            <Select value={periodoF} onChange={(e) => setPeriodoF(e.target.value)} className="w-full py-2 px-3 rounded-lg border border-[#DADADA] text-sm"><option value="">Todos</option>{PERIODOS.map((p) => <option key={p}>{p}</option>)}</Select>
          </div>
          <div><label className="text-xs text-[#666666] mb-1 block">Status</label>
            <Select value={statusF} onChange={(e) => setStatusF(e.target.value)} className="w-full py-2 px-3 rounded-lg border border-[#DADADA] text-sm"><option value="">Todos</option>{["Pendente", "Confirmado", "Em Andamento", "Finalizado", "Cancelado"].map((s) => <option key={s}>{s}</option>)}</Select>
          </div>
        </div>
        <div className="flex justify-end gap-2 mt-4">
          <button onClick={() => setGerado(true)} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#B20000] hover:bg-[#7E0000] flex items-center gap-1.5">
            <BarChart3 size={15} /> Gerar
          </button>
          <button onClick={exportarSVG} className="px-4 py-2 rounded-lg text-sm font-medium text-gray-700 border border-[#DADADA] hover:bg-[#F8F8F8] flex items-center gap-1.5">
            <Download size={15} /> Exportar SVG
          </button>
          <button onClick={() => { const titulo = document.title; document.title = "Relatório de atendimentos - SIGEP"; window.addEventListener("afterprint", () => { document.title = titulo; }, { once: true }); window.print(); }} className="px-4 py-2 rounded-lg text-sm font-medium text-gray-700 border border-[#DADADA] hover:bg-[#F8F8F8] flex items-center gap-1.5">
            <Printer size={15} /> Imprimir
          </button>
        </div>
      </div>

      {gerado && (
        <>
          <div className="grid grid-cols-2 lg:grid-cols-5 gap-3">
            <StatCard icon={ClipboardList} label="Total no filtro" value={resultado.length} tint="bg-[#4C7EFF]/10 text-[#4C7EFF]" />
            <StatCard icon={CalendarClock} label="Pendentes" value={resultado.filter((r) => r.status === "Pendente").length} tint="bg-[#FFC24C]/15 text-[#A66F00]" />
            <StatCard icon={CalendarCheck} label="Finalizados" value={resultado.filter((r) => r.status === "Finalizado").length} tint="bg-[#A0C340]/15 text-[#5F7A1F]" />
            <StatCard icon={CalendarX} label="Cancelados" value={resultado.filter((r) => r.status === "Cancelado").length} tint="bg-[#FF4C4D]/10 text-[#B20000]" />
            <StatCard icon={Clock} label="Em andamento" value={resultado.filter((r) => r.status === "Em Andamento").length} tint="bg-[#8A29E6]/10 text-[#8A29E6]" />
          </div>
          <ChartCard title="Distribuição por status">
            <ResponsiveContainer width="100%" height={220}>
              <BarChart data={porStatus}>
                <CartesianGrid strokeDasharray="3 3" stroke="#E6E6E6" />
                <XAxis dataKey="status" tick={{ fontSize: 11, fill: "#666666" }} axisLine={false} tickLine={false} />
                <YAxis tick={{ fontSize: 12, fill: "#666666" }} axisLine={false} tickLine={false} allowDecimals={false} />
                <Tooltip />
                <Bar isAnimationActive={!REDUCE_MOTION} dataKey="total" radius={[4, 4, 0, 0]} fill="#B20000" />
              </BarChart>
            </ResponsiveContainer>
          </ChartCard>
          <DataTable
            columns={[
              { key: "id", label: "ID" },
              { key: "aluno", label: "Aluno", render: (a) => alunoNome(alunos, a.alunoRm) },
              { key: "orientador", label: "Orientador", render: (a) => orientadorNome(orientadores, a.orientadorId) },
              { key: "data", label: "Data", render: (a) => formatDate(a.data) },
              { key: "motivo", label: "Motivo" },
              { key: "status", label: "Status", render: (a) => <Badge status={a.status} /> },
            ]}
            rows={resultado}
            loading={false}
            emptyTitle="Nenhum registro para os filtros aplicados"
          />
        </>
      )}
    </div>
  );
}

/* ============================================================
   INSTITUIÇÃO (config)
   ============================================================ */
function InstituicaoPage({ ctx }) {
  const { instituicao, setInstituicao, addToast } = ctx;
  const [form, setForm] = useState(instituicao);
  const [editing, setEditing] = useState(false);
  const [errors, setErrors] = useState({});

  function validate() {
    const e = {};
    if (!form.nome.trim()) e.nome = "Informe o nome da instituição.";
    if (!isValidEmail(form.email)) e.email = "Informe um e-mail válido.";
    setErrors(e);
    return Object.keys(e).length === 0;
  }
  function save() {
    if (!validate()) return;
    setInstituicao(form);
    setEditing(false);
    addToast("Dados da instituição atualizados com sucesso.", "success");
  }

  return (
    <div className="max-w-2xl bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-6">
      <div className="flex items-center gap-3 mb-6">
        <div className="w-14 h-14 rounded-xl bg-[#7E0000] flex items-center justify-center text-white shrink-0">
          <Building2 size={24} />
        </div>
        <div>
          <p className="font-semibold text-gray-800">{instituicao.nome}</p>
          <p className="text-xs text-gray-400">Dados institucionais</p>
        </div>
      </div>
      <Field label="Nome" required error={errors.nome}><TextInput disabled={!editing} value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })} error={errors.nome} /></Field>
      <div className="grid grid-cols-2 gap-x-4">
        <Field label="CNPJ"><TextInput disabled={!editing} value={form.cnpj} onChange={(e) => setForm({ ...form, cnpj: e.target.value })} /></Field>
        <Field label="Telefone"><TextInput disabled={!editing} value={form.telefone} onChange={(e) => setForm({ ...form, telefone: maskPhone(e.target.value) })} /></Field>
      </div>
      <Field label="Endereço"><TextInput disabled={!editing} value={form.endereco} onChange={(e) => setForm({ ...form, endereco: e.target.value })} /></Field>
      <Field label="E-mail" required error={errors.email}><TextInput disabled={!editing} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} error={errors.email} /></Field>
      <div className="flex justify-end gap-2 pt-2">
        {editing ? (
          <>
            <button onClick={() => { setForm(instituicao); setEditing(false); }} className="px-4 py-2 rounded-lg text-sm font-medium text-[#666666] hover:bg-[#E6E6E6]">Cancelar</button>
            <button onClick={save} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#B20000] hover:bg-[#7E0000]">Salvar alterações</button>
          </>
        ) : (
          <button onClick={() => setEditing(true)} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#7E0000] hover:bg-[#B20000] flex items-center gap-1.5"><Pencil size={15} /> Editar dados</button>
        )}
      </div>
    </div>
  );
}

/* ============================================================
   CONFIGURAÇÕES
   ============================================================ */
function ConfiguracoesPage({ ctx }) {
  const { addToast } = ctx;
  const [prefs, setPrefs] = useState({ notifEmail: true, notifSistema: true, confirmarExclusao: true, conflitoHorario: true });
  function toggle(key) {
    setPrefs((p) => ({ ...p, [key]: !p[key] }));
    addToast("Configuração atualizada.", "success");
  }
  const items = [
    { key: "notifEmail", label: "Notificações por e-mail", desc: "Enviar avisos de agendamento e cancelamento por e-mail." },
    { key: "notifSistema", label: "Notificações no sistema", desc: "Exibir alertas na central de notificações." },
    { key: "confirmarExclusao", label: "Confirmar antes de excluir", desc: "Solicitar confirmação em ações críticas de exclusão." },
    { key: "conflitoHorario", label: "Bloquear conflito de horário", desc: "Impedir agendamentos duplicados para o mesmo orientador." },
  ];
  return (
    <div className="max-w-2xl bg-white rounded-xl border border-[#E6E6E6] shadow-sm divide-y divide-gray-50">
      {items.map((it) => (
        <div key={it.key} className="flex items-center justify-between p-4">
          <div>
            <p className="text-sm font-medium text-gray-700">{it.label}</p>
            <p className="text-xs text-gray-400">{it.desc}</p>
          </div>
          <button role="switch" aria-checked={!!prefs[it.key]} aria-label={it.label} onClick={() => toggle(it.key)} className={`w-11 h-6 rounded-full transition-colors relative shrink-0 ${prefs[it.key] ? "bg-[#B20000]" : "bg-[#DADADA]"}`}>
            <span className={`absolute top-0.5 w-5 h-5 bg-white rounded-full shadow transition-all ${prefs[it.key] ? "left-5" : "left-0.5"}`} />
          </button>
        </div>
      ))}
    </div>
  );
}

/* ============================================================
   PERFIL — ACESSIBILIDADE
   ============================================================ */
function A11ySwitch({ checked, onChange, label }) {
  return (
    <button
      type="button" role="switch" aria-checked={checked} aria-label={label}
      onClick={() => onChange(!checked)}
      className={`w-11 h-6 rounded-full transition-colors relative shrink-0 ${checked ? "bg-[#B20000]" : "bg-[#DADADA]"}`}
    >
      <span className={`absolute top-0.5 w-5 h-5 bg-white rounded-full shadow transition-all ${checked ? "left-5" : "left-0.5"}`} />
    </button>
  );
}

function AcessibilidadeCard({ ctx }) {
  const { a11y, setA11y } = ctx;
  const foundIdx = FONT_STEPS.indexOf(a11y.fontScale);
  const fontIdx = foundIdx === -1 ? FONT_STEPS.indexOf(100) : foundIdx;
  const sysReduce = prefersReducedMotion();
  const stepBtn = "min-w-[2.75rem] px-3 py-2 rounded-lg text-sm font-semibold border border-[#DADADA] text-gray-700 hover:bg-[#E6E6E6] disabled:opacity-40 disabled:cursor-not-allowed";
  const letterLabel = a11y.letter === 0 ? "Padrão" : `${(a11y.letter * 0.02).toFixed(2).replace(".", ",")} em`;
  const lineLabel = a11y.line === 0 ? "Padrão" : `${(1.1 + 0.1 * a11y.line).toFixed(1).replace(".", ",")}×`;

  return (
    <div className="max-w-2xl bg-white rounded-xl border border-[#E6E6E6] shadow-sm divide-y divide-[#E6E6E6]">
      <div className="p-4">
        <p className="font-semibold text-gray-800">Acessibilidade</p>
        <p className="text-xs text-[#666666]">Ajuste o SIGEP ao seu jeito. As escolhas ficam salvas neste navegador.</p>
      </div>

      <div className="p-4 flex items-center justify-between gap-4 flex-wrap">
        <div>
          <p className="text-sm font-medium text-gray-700">Tamanho da fonte</p>
          <p className="text-xs text-[#666666]">Aumenta ou diminui o texto de todo o sistema.</p>
        </div>
        <div className="flex items-center gap-2">
          <button type="button" aria-label="Diminuir tamanho da fonte" disabled={fontIdx <= 0} onClick={() => setA11y((p) => ({ fontScale: FONT_STEPS[Math.max(0, FONT_STEPS.indexOf(p.fontScale) - 1)] }))} className={stepBtn}>A−</button>
          <span className="w-14 text-center text-sm font-medium text-gray-700" aria-live="polite">{FONT_STEPS[fontIdx]}%</span>
          <button type="button" aria-label="Aumentar tamanho da fonte" disabled={fontIdx >= FONT_STEPS.length - 1} onClick={() => setA11y((p) => ({ fontScale: FONT_STEPS[Math.min(FONT_STEPS.length - 1, FONT_STEPS.indexOf(p.fontScale) + 1)] }))} className={stepBtn}>A+</button>
        </div>
      </div>

      <div className="p-4">
        <p className="text-sm font-medium text-gray-700">Fonte para leitura</p>
        <p className="text-xs text-[#666666] mb-3">Fontes pensadas para facilitar a leitura, inclusive para quem tem dislexia.</p>
        <div className="flex flex-wrap gap-2" role="group" aria-label="Fonte para leitura">
          {FONT_OPTIONS.map((f) => (
            <button
              key={f.key} type="button" aria-pressed={a11y.font === f.key}
              onClick={() => setA11y({ font: f.key })}
              style={{ fontFamily: f.family }}
              className={`px-3 py-2 rounded-lg text-sm border ${a11y.font === f.key ? "bg-[#B20000] text-white border-[#B20000]" : "border-[#DADADA] text-gray-700 hover:bg-[#E6E6E6]"}`}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      <div className="p-4">
        <div className="flex items-center justify-between mb-2">
          <label htmlFor="a11y-letter" className="text-sm font-medium text-gray-700">Espaçamento entre letras</label>
          <span className="text-xs text-[#666666]">{letterLabel}</span>
        </div>
        <input id="a11y-letter" type="range" min={0} max={10} step={1} value={a11y.letter} aria-valuetext={letterLabel}
          onChange={(e) => setA11y({ letter: Number(e.target.value) })} className="w-full accent-[#B20000]" />
      </div>

      <div className="p-4">
        <div className="flex items-center justify-between mb-2">
          <label htmlFor="a11y-line" className="text-sm font-medium text-gray-700">Espaçamento entre linhas</label>
          <span className="text-xs text-[#666666]">{lineLabel}</span>
        </div>
        <input id="a11y-line" type="range" min={0} max={13} step={1} value={a11y.line} aria-valuetext={lineLabel}
          onChange={(e) => setA11y({ line: Number(e.target.value) })} className="w-full accent-[#B20000]" />
      </div>

      <div className="p-4 flex items-center justify-between gap-4">
        <div>
          <p className="text-sm font-medium text-gray-700">Alvos de clique maiores</p>
          <p className="text-xs text-[#666666]">Botões e campos ficam com pelo menos 44 px, mais fáceis de tocar e clicar.</p>
        </div>
        <A11ySwitch checked={!!a11y.targets} onChange={(v) => setA11y({ targets: v })} label="Alvos de clique maiores" />
      </div>

      <div className="p-4 flex items-center justify-between gap-4">
        <div>
          <p className="text-sm font-medium text-gray-700">Reduzir animações</p>
          <p className="text-xs text-[#666666]">Diminui transições e movimentos na tela. Já começa ligado se o seu sistema pedir menos movimento.</p>
        </div>
        <A11ySwitch checked={a11y.motion === "reduce" || (a11y.motion === "system" && sysReduce)} onChange={(v) => setA11y({ motion: v ? "reduce" : "full" })} label="Reduzir animações" />
      </div>

      <div className="p-4 flex items-center justify-between gap-4">
        <div>
          <p className="text-sm font-medium text-gray-700">VLibras</p>
          <p className="text-xs text-[#666666]">Tradutor de Português para Libras do governo federal. Ao ativar, um botão aparece na lateral da tela. Precisa de internet.</p>
        </div>
        <A11ySwitch checked={!!a11y.vlibras} onChange={(v) => setA11y({ vlibras: v })} label="Ativar VLibras" />
      </div>

      <div className="p-4 flex justify-end">
        <button type="button" onClick={() => setA11y({ ...A11Y_DEFAULT })} className="px-4 py-2 rounded-lg text-sm font-medium text-[#666666] hover:bg-[#E6E6E6]">Restaurar padrões</button>
      </div>
    </div>
  );
}

/* ============================================================
   PERFIL — ALTERAR SENHA (somente interface)
   A troca real depende da autenticação no servidor, que ainda não está integrada. Por isso esta tela só VALIDA os campos:
   não altera senha nenhuma, não simula sucesso e não guarda a senha digitada (os campos são limpos).
   TODO(API): PUT API_ROTAS.senha com { senhaAtual, novaSenha }, usando o cookie de sessão e o cabeçalho X-CSRF-Token.
   ============================================================ */
function AlterarSenhaCard() {
  const vazio = { atual: "", nova: "", confirmar: "" };
  const [f, setF] = useState(vazio);
  const [mostrar, setMostrar] = useState(false);
  const [erros, setErros] = useState({});
  const [aviso, setAviso] = useState(false);

  function enviar() {
    const e = {};
    if (!f.atual) e.atual = "Informe a senha atual.";
    if (!f.nova) e.nova = "Informe a nova senha.";
    else if (f.nova.length < 8 || !/[A-Za-z]/.test(f.nova) || !/\d/.test(f.nova)) e.nova = "Use ao menos 8 caracteres, com letras e números.";
    else if (f.atual && f.nova === f.atual) e.nova = "A nova senha deve ser diferente da atual.";
    if (!f.confirmar) e.confirmar = "Confirme a nova senha.";
    else if (f.confirmar !== f.nova) e.confirmar = "A confirmação não é igual à nova senha.";
    setErros(e);
    setAviso(false);
    if (Object.keys(e).length) return;
    setF(vazio); // nada é salvo: a senha digitada é descartada
    setAviso(true);
  }
  const tipo = mostrar ? "text" : "password";
  return (
    <div className="max-w-xl bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-6">
      <p className="font-semibold text-gray-800">Alterar senha</p>
      <p className="text-xs text-[#666666] mb-4">Use ao menos 8 caracteres, com letras e números.</p>
      <Field label="Senha atual" required error={erros.atual}><TextInput type={tipo} autoComplete="current-password" value={f.atual} onChange={(e) => setF({ ...f, atual: e.target.value })} error={erros.atual} /></Field>
      <Field label="Nova senha" required error={erros.nova}><TextInput type={tipo} autoComplete="new-password" value={f.nova} onChange={(e) => setF({ ...f, nova: e.target.value })} error={erros.nova} /></Field>
      <Field label="Confirmar nova senha" required error={erros.confirmar}><TextInput type={tipo} autoComplete="new-password" value={f.confirmar} onChange={(e) => setF({ ...f, confirmar: e.target.value })} error={erros.confirmar} /></Field>
      <label className="flex items-center gap-2 text-xs text-[#666666] mb-4 cursor-pointer"><input type="checkbox" checked={mostrar} onChange={(e) => setMostrar(e.target.checked)} className="accent-[#B20000]" /> Mostrar senhas</label>
      {aviso && (
        <div role="status" className="flex items-start gap-2 rounded-lg border border-[#FFC24C]/60 bg-[#FFC24C]/15 px-3 py-2 mb-4 text-sm text-[#8A5A00]">
          <Info size={16} className="mt-0.5 shrink-0" />
          <span>Os campos estão corretos, mas <strong>a senha ainda não foi alterada</strong>: esta função será ativada quando o sistema for integrado ao servidor de autenticação.</span>
        </div>
      )}
      <div className="flex justify-end">
        <button type="button" onClick={enviar} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#B20000] hover:bg-[#7E0000]">Alterar senha</button>
      </div>
    </div>
  );
}

/* ============================================================
   PERFIL (comum a todos os perfis)
   ============================================================ */
function PerfilPage({ ctx }) {
  const { role, currentUser, addToast } = ctx;
  const [form, setForm] = useState({ nome: currentUser.nome, email: currentUser.email });
  const [editing, setEditing] = useState(false);
  const [errors, setErrors] = useState({});

  function save() {
    const e = {};
    if (!form.nome.trim()) e.nome = "Informe seu nome.";
    if (!isValidEmail(form.email)) e.email = "E-mail inválido.";
    setErrors(e);
    if (Object.keys(e).length) return;
    setEditing(false);
    addToast("Perfil atualizado com sucesso.", "success");
  }

  return (
    <div className="space-y-5">
    <div className="max-w-xl bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-6">
      <div className="flex items-center gap-4 mb-6">
        <div className="w-16 h-16 rounded-full bg-[#B20000] text-white flex items-center justify-center text-xl font-semibold">{currentUser.iniciais}</div>
        <div>
          <p className="font-semibold text-gray-800 text-lg">{currentUser.nome}</p>
          <p className="text-sm text-gray-400">{ROLE_LABEL[role]}</p>
        </div>
      </div>
      <Field label="Nome" required error={errors.nome}><TextInput disabled={!editing} value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })} error={errors.nome} /></Field>
      <Field label="E-mail" required error={errors.email}><TextInput disabled={!editing} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} error={errors.email} /></Field>
      <div className="flex justify-end gap-2 pt-2">
        {editing ? (
          <>
            <button onClick={() => { setEditing(false); setForm({ nome: currentUser.nome, email: currentUser.email }); }} className="px-4 py-2 rounded-lg text-sm font-medium text-[#666666] hover:bg-[#E6E6E6]">Cancelar</button>
            <button onClick={save} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#B20000] hover:bg-[#7E0000]">Salvar alterações</button>
          </>
        ) : (
          <button onClick={() => setEditing(true)} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#7E0000] hover:bg-[#B20000] flex items-center gap-1.5"><Pencil size={15} /> Editar perfil</button>
        )}
      </div>
    </div>
    <AlterarSenhaCard />
    <AcessibilidadeCard ctx={ctx} />
    </div>
  );
}

/* ============================================================
