  const realizados = mine.filter((a) => a.status === "Finalizado").length;
  const pendentes = mine.filter((a) => a.status === "Pendente").length;
  const cancelados = mine.filter((a) => a.status === "Cancelado").length;

  const meses = last6Months();
  const porMes = meses.map((m) => ({
    mes: m.label,
    total: mine.filter((a) => {
      const d = parseDay(a.data);
      return `${d.getFullYear()}-${d.getMonth()}` === m.key;
    }).length,
  }));
  const STATUS_CHART = { Pendente: "#FFC24C", Confirmado: "#4C7EFF", "Em Andamento": "#F59E0B", Finalizado: "#A0C340", Cancelado: "#F95B4D" };
