/* ============================================================
   RESPONSÁVEL — SOLICITAR ATENDIMENTO
   ============================================================ */
function SolicitarPage({ ctx }) {
  const { alunos, currentUserId, orientadores, atendimentos, setAtendimentos, addToast, setPage, disponibilidades, reunioes } = ctx;
  const meus = ctx.alunosDoResp(currentUserId);
  const [form, setForm] = useState({ alunoRm: meus[0]?.rm || "", orientadorId: orientadores[0]?.id || "", data: "", horario: "", motivo: "", descricao: "" });
  const [errors, setErrors] = useState({});
  const [sent, setSent] = useState(false);
  // Horários oferecidos = disponibilidade cadastrada pela orientadora (períodos − intervalos − atendimentos já marcados).
  // TODO(API): trocar por GET /api/orientadores/{id}/horarios?data=... (ver API_ROTAS).
  const bloqueadoPorReuniao = reuniaoAtivaNoDia(reunioes, form.data);
  const permitidos = useMemo(() => bloqueadoPorReuniao ? [] : minutosLivres(disponibilidades, atendimentos, form.orientadorId, form.data), [disponibilidades, atendimentos, reunioes, form.orientadorId, form.data, bloqueadoPorReuniao]);
  const faixas = useMemo(() => faixasDe(permitidos), [permitidos]);
  const temDisp = disponibilidades.some((d) => d.orientadorId === form.orientadorId);
  useEffect(() => { if (form.horario && !permitidos.includes(toMin(form.horario))) setForm((f) => ({ ...f, horario: "" })); }, [permitidos]);

  function validate() {
    const e = {};
    if (!form.alunoRm) e.alunoRm = "Selecione um aluno.";
    if (!form.orientadorId) e.orientadorId = "Selecione um orientador.";
    if (!form.data) e.data = "Selecione a data desejada.";
    else if (form.data < dateKey(TODAY)) e.data = "A data não pode ser no passado.";
    if (!form.horario) e.horario = "Selecione o horário desejado.";
    if (!form.motivo.trim()) e.motivo = "Informe o motivo do atendimento.";
    if (form.motivo === "Outro" && !form.descricao.trim()) e.descricao = "Escolheu \"Outro\": descreva o motivo específico da solicitação.";
    if (form.data && bloqueadoPorReuniao) e.data = "Há uma reunião nesta data. Não é possível solicitar atendimento nesse dia.";
    if (form.data && form.horario && !permitidos.includes(toMin(form.horario))) e.horario = "Este horário não está disponível. Escolha outro horário.";
    if (form.data && form.horario) {
      const idsResponsaveis = ctx.respIdsDe(form.alunoRm);
      const conflito = conflitoDeCompromisso({ pessoaIds: [form.orientadorId, currentUserId, ...idsResponsaveis], data: form.data, inicio: toMin(form.horario), fim: toMin(form.horario) + DURACAO_ATENDIMENTO, atendimentos, reunioes });
      if (conflito) e.horario = conflito;
      if (atendimentos.some(a => a.alunoRm === form.alunoRm && a.data === form.data && ATIVOS.includes(a.status) && intervalosSeSobrepoem(toMin(form.horario), toMin(form.horario)+DURACAO_ATENDIMENTO, toMin(a.horario), toMin(a.horario)+DURACAO_ATENDIMENTO))) e.horario = "Este aluno já possui um compromisso nesse intervalo.";
    }
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  function submit() {
    if (!validate()) return;
    const aluno = alunos.find((a) => a.rm === form.alunoRm);
    const novo = {
      id: uid("A"),
      alunoRm: form.alunoRm,
      orientadorId: form.orientadorId,
      responsavelId: currentUserId,
      responsaveisIds: ctx.respIdsDe(form.alunoRm),
      data: form.data,
      horario: form.horario,
      motivo: form.motivo,
      descricao: form.descricao,
      observacoes: "",
      resultado: "",
      status: "Pendente",
      criadoEm: dateKey(TODAY),
    };
    setAtendimentos((prev) => [novo, ...prev]);
    addToast("Solicitação de atendimento enviada com sucesso.", "success");
    setSent(true);
  }

  if (sent) {
    return (
      <div className="max-w-lg mx-auto bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-8 text-center">
        <CheckCircle2 size={44} className="text-[#A0C340] mx-auto mb-4" />
        <h3 className="font-semibold text-gray-800 text-lg mb-1">Solicitação enviada!</h3>
        <p className="text-sm text-[#666666] mb-6">O orientador foi notificado e irá confirmar a disponibilidade do horário solicitado. Você receberá uma notificação assim que houver retorno.</p>
        <div className="flex justify-center gap-2">
          <button onClick={() => setPage("agendamentos")} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#B20000] hover:bg-[#7E0000]">Ver meus agendamentos</button>
          <button onClick={() => { setSent(false); setForm({ alunoRm: meus[0]?.rm || "", orientadorId: orientadores[0]?.id || "", data: "", horario: "", motivo: "", descricao: "" }); }} className="px-4 py-2 rounded-lg text-sm font-medium text-[#666666] border border-[#DADADA] hover:bg-[#F8F8F8]">
            Nova solicitação
          </button>
        </div>
      </div>
    );
  }

  const disponibilidadeOrientador = disponibilidades.filter((d) => d.orientadorId === form.orientadorId).sort((a,b) => a.dia-b.dia || a.inicio.localeCompare(b.inicio));
  const disponibilidadeData = form.data ? disponibilidadeOrientador.filter((d) => d.dia === diaDe(form.data)) : [];
  return (
    <div className="max-w-6xl grid grid-cols-1 lg:grid-cols-2 gap-6 items-start">
    <div className="bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-6">
      <p className="text-sm text-[#666666] mb-5">Preencha os dados abaixo para solicitar um atendimento pedagógico. O orientador confirmará a disponibilidade.</p>
      <Field label="Aluno" required error={errors.alunoRm}>
        <Select busca value={form.alunoRm} onChange={(e) => setForm({ ...form, alunoRm: e.target.value })} error={errors.alunoRm}>
          {meus.map((a) => <option key={a.rm} value={a.rm}>{a.nome} — RM {a.rm}</option>)}
        </Select>
      </Field>
      <Field label="Orientador" required error={errors.orientadorId}>
        <Select busca value={form.orientadorId} onChange={(e) => setForm({ ...form, orientadorId: e.target.value })} error={errors.orientadorId}>
          {orientadores.map((o) => <option key={o.id} value={o.id}>{o.nome}</option>)}
        </Select>
      </Field>
      <div className="grid grid-cols-2 gap-x-4">
        <Field label="Data desejada" required error={errors.data}>
          <input type="date" min={dateKey(TODAY)} value={form.data} onChange={(e) => setForm({ ...form, data: e.target.value })} className={inputCls(errors.data)} />
        </Field>
        <Field label="Horário desejado" required error={errors.horario}>
          <SeletorHorario value={form.horario} onChange={(v) => setForm({ ...form, horario: v })} permitidos={permitidos} error={errors.horario} disabled={!form.data} />
        </Field>
      </div>
      {form.orientadorId && (
        <p className="text-xs text-[#666666] -mt-2 mb-4" role="status">
          {bloqueadoPorReuniao
            ? "Há uma reunião nesta data. O dia inteiro está indisponível para atendimentos."
            : !temDisp
            ? "Esta orientadora ainda não cadastrou períodos de disponibilidade."
            : !form.data
            ? "Escolha a data para ver os horários disponíveis."
            : faixas.length === 0
            ? "Não há horários disponíveis nesta data. Escolha outro dia."
            : `Você pode escolher qualquer minuto de início entre ${faixas.map((f) => `${f.ini} e ${f.fim}`).join(" · ")} (cada atendimento dura ${DURACAO_ATENDIMENTO} min).`}
        </p>
      )}
      <Field label="Motivo" required error={errors.motivo}>
        <Select value={form.motivo} onChange={(e) => setForm({ ...form, motivo: e.target.value })} error={errors.motivo}>
          <option value="">Selecione...</option>
          {MOTIVOS.map((m) => <option key={m}>{m}</option>)}
        </Select>
      </Field>
      <Field label="Descrição" required={form.motivo === "Outro"} error={errors.descricao}>
        <TextArea error={errors.descricao} value={form.descricao} onChange={(e) => setForm({ ...form, descricao: e.target.value })} placeholder={form.motivo === "Outro" ? "Você escolheu \"Outro\": descreva aqui o motivo específico da solicitação" : "Descreva com mais detalhes o motivo da solicitação (opcional)"} />
      </Field>
      <button onClick={submit} className="w-full mt-2 py-2.5 rounded-lg bg-[#B20000] hover:bg-[#7E0000] text-white text-sm font-medium flex items-center justify-center gap-1.5">
        <ClipboardCheck size={16} /> Solicitar atendimento
      </button>
    </div>
    <aside className="bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-6 min-h-[22rem]">
      <div className="flex items-center gap-2 mb-2"><CalendarClock size={18} className="text-[#B20000]"/><h3 className="font-semibold text-gray-800">Disponibilidade do orientador</h3></div>
      <p className="text-sm text-gray-500 mb-4">{orientadores.find(o=>o.id===form.orientadorId)?.nome || "Selecione um orientador"}</p>
      {!form.orientadorId ? <p className="text-sm text-gray-500">Selecione um orientador para consultar os horários.</p> : !disponibilidadeOrientador.length ? <p className="text-sm text-gray-500">Este orientador ainda não cadastrou horários de disponibilidade.</p> : <div className="space-y-2">
        {(form.data ? disponibilidadeData : disponibilidadeOrientador).map((d,i)=><div key={d.id || i} className="rounded-lg border border-[#E6E6E6] p-3"><p className="text-sm font-medium text-gray-800">{DIAS[d.dia]}</p><p className="text-sm text-gray-600">{d.inicio} às {d.fim}</p>{(d.intervalos||[]).length>0&&<p className="text-xs text-gray-500 mt-1">Intervalos: {d.intervalos.map(x=>`${x.inicio}–${x.fim}`).join(", ")}</p>}</div>)}
        {form.data && disponibilidadeData.length===0 && <p className="text-sm text-gray-500">Não há período cadastrado para {DIAS[diaDe(form.data)]}.</p>}
      </div>}
      {form.data && <div className="mt-4 rounded-lg bg-[#F8F8F8] p-3"><p className="text-xs font-semibold text-gray-700 mb-1">Horários livres em {formatDate(form.data)}</p><p className="text-sm text-gray-600">{bloqueadoPorReuniao ? "Data bloqueada por reunião." : faixas.length ? faixas.map(f=>`${f.ini}–${f.fim}`).join(" · ") : "Nenhum horário livre nesta data."}</p></div>}
    </aside>
    </div>
  );
}

