function RespAgendamentosPage({ ctx }) {
  const { atendimentos, setAtendimentos, alunos, orientadores, currentUserId, addToast, askConfirm } = ctx;
  const rmsMeus = ctx.alunosDoResp(currentUserId).map((x) => x.rm);
  const mine = atendimentos.filter((a) => (a.responsavelId === currentUserId || rmsMeus.includes(a.alunoRm)) && ["Pendente", "Confirmado", "Em Andamento"].includes(a.status)).sort((a, b) => (a.data < b.data ? 1 : -1));

  function cancelar(item) {
    askConfirm({
      title: "Cancelar agendamento",
      message: `Deseja cancelar o agendamento de ${alunoNome(alunos, item.alunoRm)} em ${formatDate(item.data)} às ${item.horario}?`,
      danger: true, confirmLabel: "Cancelar agendamento",
      onConfirm: () => {
        setAtendimentos((prev) => prev.map((a) => (a.id === item.id ? { ...a, status: "Cancelado" } : a)));
        addToast("Agendamento cancelado com sucesso.", "success");
      },
    });
  }

  const columns = [
    { key: "aluno", label: "Aluno", render: (a) => alunoNome(alunos, a.alunoRm) },
    { key: "orientador", label: "Orientador", render: (a) => orientadorNome(orientadores, a.orientadorId) },
    { key: "data", label: "Data", render: (a) => formatDate(a.data) },
    { key: "horario", label: "Horário" },
    { key: "motivo", label: "Motivo" },
    { key: "status", label: "Status", render: (a) => <Badge status={a.status} /> },
    {
      key: "acoes", label: "Ações", render: (a) => (
        ["Pendente", "Confirmado"].includes(a.status) ? (
          <button onClick={() => cancelar(a)} className="text-xs font-medium text-[#B20000] hover:underline flex items-center gap-1"><Ban size={13} /> Cancelar</button>
        ) : <span className="text-xs text-gray-300">—</span>
      ),
    },
  ];
  return <DataTable columns={columns} rows={mine} loading={false} emptyTitle="Nenhum agendamento encontrado" emptyMessage="Solicite um atendimento para começar." />;
}

