/* ============================================================
   NOVOS MÓDULOS — usuários, solicitações, disponibilidade,
   reuniões, auditoria e notificações (front-end com dados locais;
   as funções save/log/notify são os pontos onde a API PHP/MySQL entra)
   ============================================================ */
const DIAS = ["Domingo", "Segunda-feira", "Terça-feira", "Quarta-feira", "Quinta-feira", "Sexta-feira", "Sábado"];
const PERFIS = { instituicao: "Administrador", orientador: "Orientador", responsavel: "Responsável" };
const HORAS_PADRAO = ["08:00", "08:30", "09:00", "09:30", "10:00", "10:30", "13:00", "13:30", "14:00", "14:30", "15:00", "15:30"];
const ATIVOS = ["Confirmado", "Em Andamento"];
const btnP = "px-4 py-2 rounded-lg bg-[#B20000] hover:bg-[#7E0000] text-white text-sm font-medium flex items-center gap-1.5";
const btnS = "px-4 py-2 rounded-lg border border-[#DADADA] text-sm font-medium text-gray-700 hover:bg-[#E6E6E6]";
const toMin = (h) => { const [a, b] = h.split(":").map(Number); return a * 60 + b; };
const fromMin = (m) => `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`;
const fmtDT = (iso) => new Date(iso).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
const diaDe = (data) => new Date(data + "T12:00:00").getDay();
const intervalosSeSobrepoem = (inicioA, fimA, inicioB, fimB) => inicioA < fimB && inicioB < fimA;
const fimAtendimento = (a) => fromMin(toMin(a.horario) + DURACAO_ATENDIMENTO);
const reuniaoAtivaNoDia = (reunioes, data, ignorarId = null) => reunioes.some((r) => r.id !== ignorarId && r.data === data && r.status !== "Cancelada");
function conflitoDeCompromisso({ pessoaIds, data, inicio, fim, atendimentos, reunioes, ignorarAtendimento = null, ignorarReuniao = null }) {
  const pessoas = new Set(pessoaIds.filter(Boolean));
  const conflitoAtendimento = atendimentos.find((a) => a.id !== ignorarAtendimento && a.data === data && ATIVOS.includes(a.status) && intervalosSeSobrepoem(inicio, fim, toMin(a.horario), toMin(a.horario) + DURACAO_ATENDIMENTO) && ([a.orientadorId, a.responsavelId, ...(a.responsaveisIds || [])].some(id => pessoas.has(id))));
  if (conflitoAtendimento) return `Conflito com atendimento das ${conflitoAtendimento.horario} às ${fimAtendimento(conflitoAtendimento)}.`;
  const conflitoReuniao = reunioes.find((r) => r.id !== ignorarReuniao && r.data === data && r.status !== "Cancelada" && intervalosSeSobrepoem(inicio, fim, toMin(r.horario), toMin(r.horarioFim || r.horario)) && ([r.criadoPor, ...(r.participantes || [])].some((id) => pessoas.has(id))));
  if (conflitoReuniao) return `Conflito com a reunião “${conflitoReuniao.assunto}” (${conflitoReuniao.horario} às ${conflitoReuniao.horarioFim || conflitoReuniao.horario}).`;
  return "";
}


/* ============================================================
   DISPONIBILIDADE → HORÁRIOS DO RESPONSÁVEL
   A disponibilidade cadastrada pela orientadora (períodos por dia da semana, cada um com até 5 intervalos) é a ÚNICA
   fonte dos horários oferecidos ao responsável. Hoje ela vive no estado do React (some ao recarregar a página).
   TODO(API): com o back-end integrado, leitura e gravação passam a usar as rotas de API_ROTAS, sem mudar as telas;
   minutosLivres() será substituída por GET /api/orientadores/{id}/horarios?data=AAAA-MM-DD.
   ============================================================ */
const API_ROTAS = {
  disponibilidades: "/api/disponibilidades",                 // GET (lista), POST, PUT /{id}, DELETE /{id}
  horariosLivres: "/api/orientadores/{id}/horarios?data=",   // GET → horários livres da orientadora na data
  solicitacoes: "/api/solicitacoes",                         // POST
  senha: "/api/perfil/senha",                                // PUT { senhaAtual, novaSenha }
  vinculosResponsavelAluno: "/api/alunos/{rm}/responsaveis", // GET/PUT (tabela responsavel_aluno)
};
const DURACAO_ATENDIMENTO = 30; // minutos
const MAX_INTERVALOS = 5;       // intervalos (almoço, pausas) por período de disponibilidade

/** Minutos de INÍCIO que o responsável pode escolher: dentro de um período, fora dos intervalos e sem choque com atendimento ativo. */
function minutosLivres(disp, atend, orientadorId, data) {
  if (!data || !orientadorId) return [];
  const ocupados = atend.filter((a) => a.orientadorId === orientadorId && a.data === data && ATIVOS.includes(a.status)).map((a) => toMin(a.horario));
  const agora = new Date().getHours() * 60 + new Date().getMinutes();
  const out = new Set();
  disp.filter((d) => d.orientadorId === orientadorId && d.dia === diaDe(data)).forEach((d) => {
    const ints = (d.intervalos || []).map((i) => [toMin(i.inicio), toMin(i.fim)]);
    for (let t = toMin(d.inicio); t + DURACAO_ATENDIMENTO <= toMin(d.fim); t++) {
      if (ints.some(([x, y]) => t + DURACAO_ATENDIMENTO > x && t < y)) continue; // cai num intervalo
      if (ocupados.some((o) => Math.abs(o - t) < DURACAO_ATENDIMENTO)) continue;  // já ocupado
      if (data === dateKey(TODAY) && t <= agora) continue;                         // hoje: horário que já passou
      out.add(t);
    }
  });
  return [...out].sort((x, y) => x - y);
}
/** Agrupa minutos consecutivos em faixas ("08:00 até 11:29"). */
function faixasDe(minutos) {
  const f = [];
  minutos.forEach((m) => { const u = f[f.length - 1]; if (u && m === u[1] + 1) u[1] = m; else f.push([m, m]); });
  return f.map(([x, y]) => ({ ini: fromMin(x), fim: fromMin(y) }));
}
function foraDisponibilidade(disp, a) {
  const mine = disp.filter((d) => d.orientadorId === a.orientadorId);
  if (!mine.length) return true;
  const t = toMin(a.horario);
  return !mine.some((d) => d.dia === diaDe(a.data) && t >= toMin(d.inicio) && t + DURACAO_ATENDIMENTO <= toMin(d.fim)
    && !(d.intervalos || []).some((i) => t + DURACAO_ATENDIMENTO > toMin(i.inicio) && t < toMin(i.fim)));
}
function seedExtra(seed) {
  const o = seed.orientadores, d = (n) => dateKey(addDays(TODAY, n));
  const disp = [];
  o.slice(0, 3).forEach((x, i) => {
    [1, 3].forEach((dia) => disp.push({ id: uid("D"), orientadorId: x.id, dia, inicio: "08:00", fim: "12:00", intervalos: i === 0 && dia === 1 ? [{ inicio: "10:00", fim: "10:15" }] : [] }));
    [2, 4].forEach((dia) => disp.push({ id: uid("D"), orientadorId: x.id, dia: dia, inicio: i % 2 ? "13:00" : "14:00", fim: "17:00", intervalos: [] }));
  });
  return {
    admins: [{ id: "ADM001", nome: "Coordenação Geral", email: "coordenacao@sigep.com", telefone: "", status: "Ativo" }],
    disp,
    reunioes: Array.from({ length: 10 }, (_, i) => ({
      id: uid("M"),
      assunto: ["Alinhamento pedagógico do bimestre", "Reunião com responsáveis do 1º ano", "Conselho de acompanhamento", "Planejamento de intervenções", "Reunião de frequência escolar", "Acompanhamento de desempenho", "Orientação de estágio", "Reunião de equipe pedagógica", "Devolutiva aos responsáveis", "Planejamento de ações individuais"][i],
      descricao: "Reunião de demonstração para testes do SIGEP.",
      data: d(i < 7 ? i + 1 : -(i - 6)),
      horario: ["08:30", "09:30", "10:00", "11:00", "13:30", "14:00", "15:00", "09:00", "10:30", "14:30"][i],
      horarioFim: ["09:00", "10:00", "10:30", "11:30", "14:00", "14:30", "15:30", "09:30", "11:00", "15:00"][i],
      participantes: i % 2 ? [o[0].id, seed.responsaveis[i % seed.responsaveis.length].id] : [o[0].id, o[1].id, "ADM001"],
      status: "Agendada", criadoPor: "INST"
    })),
    audit: [
      ["Etec Heliópolis", "Administrador", "Cadastrou orientador " + o[1].nome, "Usuários", -4],
      ["Etec Heliópolis", "Administrador", "Alterou o perfil de acesso de Coordenação Geral", "Permissões", -3],
      [o[0].nome, "Orientador", "Cadastrou disponibilidade de segunda-feira", "Disponibilidade", -2],
      [o[0].nome, "Orientador", "Aprovou a solicitação de atendimento", "Solicitações", -1],
    ].map(([usuario, perfil, acao, cat, n]) => ({ id: uid("L"), usuario, perfil, acao, cat, quando: addDays(TODAY, n).toISOString() })),
  };
}
function useDiff(list, key, h) {
  const prev = useRef(list);
  useEffect(() => {
    const p = prev.current; prev.current = list;
    if (p === list) return;
    const pm = new Map(p.map((x) => [x[key], x])), nm = new Set(list.map((x) => x[key]));
    list.forEach((x) => { const o = pm.get(x[key]); if (!o) h.add && h.add(x); else if (o !== x) h.chg && h.chg(o, x); });
    p.forEach((o) => { if (!nm.has(o[key])) h.del && h.del(o); });
  }, [list]);
}

/* ---------- USUÁRIOS E PERMISSÕES ---------- */
function UsuariosPage({ ctx }) {
  const { admins, setAdmins, orientadores, setOrientadores, responsaveis, setResponsaveis, alunos, atendimentos, addToast, askConfirm, logAudit } = ctx;
  const [q, setQ] = useState(""), [pf, setPf] = useState(""), [m, setM] = useState(null), [err, setErr] = useState({});
  const all = [
    ...admins.map((u) => ({ ...u, perfil: "instituicao" })),
    ...orientadores.map((u) => ({ ...u, perfil: "orientador" })),
    ...responsaveis.map((u) => ({ ...u, perfil: "responsavel" })),
  ];
  const rows = all.filter((u) => (!pf || u.perfil === pf) && (!q || (u.nome + u.email).toLowerCase().includes(q.toLowerCase())));
  const setters = { instituicao: setAdmins, orientador: setOrientadores, responsavel: setResponsaveis };
  const prefix = { instituicao: "ADM", orientador: "O", responsavel: "R" };

  function toggle(u) {
    const novo = u.status === "Ativo" ? "Inativo" : "Ativo";
    const run = () => { setters[u.perfil]((p) => p.map((x) => (x.id === u.id ? { ...x, status: novo } : x))); addToast(novo === "Ativo" ? "Usuário reativado." : "Usuário desativado."); };
    if (novo === "Ativo") return run();
    askConfirm({ title: "Desativar usuário", message: `"${u.nome}" não poderá mais acessar o sistema. Deseja continuar?`, danger: true, confirmLabel: "Desativar", onConfirm: () => { run(); }});
  }
  function save() {
    const e = {};
    if (!m.nome.trim()) e.nome = "Informe o nome.";
    if (!/^\S+@\S+\.\S+$/.test(m.email)) e.email = "Informe um e-mail válido.";
    else if (all.some((u) => u.id !== m.id && u.email.toLowerCase() === m.email.trim().toLowerCase())) e.email = "Este e-mail já está em uso.";
    setErr(e);
    if (Object.keys(e).length) return;
    const dados = { nome: m.nome.trim(), email: m.email.trim().toLowerCase(), telefone: m.telefone };
    if (!m.id) {
      const novo = { id: uid(prefix[m.perfil]), ...dados, status: "Ativo", ...(m.perfil === "orientador" ? { cpf: "", instituicao: ctx.instituicao.nome } : {}), ...(m.perfil === "responsavel" ? { cpf: "" } : {}) };
      setters[m.perfil]((p) => [...p, novo]);
      logAudit(`Atribuiu o perfil ${PERFIS[m.perfil]} a ${dados.nome}`, "Permissões");
      addToast("Usuário cadastrado.");
    } else if (m.perfil === m.perfilOriginal) {
      setters[m.perfil]((p) => p.map((x) => (x.id === m.id ? { ...x, ...dados } : x)));
      addToast("Usuário atualizado.");
    } else {
      if (ctx.responsavelAluno.some((v) => v.responsavelId === m.id) || atendimentos.some((a) => a.orientadorId === m.id || a.responsavelId === m.id)) {
        return addToast("Não é possível alterar o perfil: há alunos ou atendimentos vinculados.", "error");
      }
      const atual = all.find((u) => u.id === m.id);
      setters[m.perfilOriginal]((p) => p.filter((x) => x.id !== m.id));
      setters[m.perfil]((p) => [...p, { ...atual, ...dados, id: uid(prefix[m.perfil]) }]);
      logAudit(`Alterou o perfil de ${dados.nome}: ${PERFIS[m.perfilOriginal]} → ${PERFIS[m.perfil]}`, "Permissões");
      addToast("Perfil de acesso alterado.");
    }
    setM(null);
  }
  const keys = [...new Set(["instituicao", "orientador", "responsavel"].flatMap((r) => MENUS[r].map((i) => i.key)))].filter((k) => k !== "perfil");
  const label = (k) => { for (const r of ["instituicao", "orientador", "responsavel"]) { const i = MENUS[r].find((x) => x.key === k); if (i) return i.label; } return k; };

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-center gap-3">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Buscar por nome ou e-mail" className={inputCls() + " max-w-xs"} aria-label="Buscar usuário" />
        <Select value={pf} onChange={(e) => setPf(e.target.value)} aria-label="Filtrar por perfil" style={{ maxWidth: "12.5rem" }}>
          <option value="">Todos os perfis</option>
          {Object.entries(PERFIS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
        </Select>
        <button className={btnP + " ml-auto"} onClick={() => { setErr({}); setM({ nome: "", email: "", telefone: "", perfil: "orientador" }); }}><Plus size={16} /> Novo usuário</button>
      </div>
      <DataTable
        columns={[
          { key: "nome", label: "Nome" }, { key: "email", label: "E-mail" },
          { key: "perfil", label: "Perfil", render: (u) => PERFIS[u.perfil] },
          { key: "status", label: "Status", render: (u) => <Badge status={u.status} /> },
          { key: "acoes", label: "Ações", render: (u) => (
            <div className="flex items-center gap-0.5">
              <IconBtn icon={Pencil} title="Editar" onClick={() => { setErr({}); setM({ ...u, perfilOriginal: u.perfil }); }} />
              <IconBtn icon={u.status === "Ativo" ? Ban : CheckCircle2} title={u.status === "Ativo" ? "Desativar" : "Reativar"} tone="danger" onClick={() => toggle(u)} />
            </div>) },
        ]}
        rows={rows}
      />
      <div className="bg-white rounded-xl border border-[#E6E6E6] shadow-sm overflow-x-auto">
        <p className="p-4 font-semibold text-gray-800 flex items-center gap-2"><ShieldCheck size={18} /> Permissões por perfil</p>
        <table className="w-full text-sm">
          <thead><tr className="bg-[#F8F8F8] text-xs uppercase text-[#666666]"><th className="text-left px-4 py-2">Funcionalidade</th>{Object.values(PERFIS).map((p) => <th key={p} className="px-4 py-2">{p}</th>)}</tr></thead>
          <tbody>{keys.map((k) => (
            <tr key={k} className="border-t border-[#E6E6E6]"><td className="px-4 py-2">{label(k)}</td>
              {["instituicao", "orientador", "responsavel"].map((r) => <td key={r} className="px-4 py-2 text-center">{MENUS[r].some((i) => i.key === k) ? <Check size={16} className="inline text-[#5F7A1F]" aria-label="Permitido" /> : <span className="text-gray-300" aria-label="Sem acesso">—</span>}</td>)}
            </tr>))}</tbody>
        </table>
      </div>
      {m && (
        <Modal title={m.id ? "Editar usuário" : "Novo usuário"} onClose={() => setM(null)} size="sm"
          footer={<><button className={btnS} onClick={() => setM(null)}>Cancelar</button><button className={btnP} onClick={save}>Salvar</button></>}>
          <Field label="Nome" required error={err.nome}><input className={inputCls(err.nome)} value={m.nome} onChange={(e) => setM({ ...m, nome: e.target.value })} /></Field>
          <Field label="E-mail" required error={err.email}><input className={inputCls(err.email)} value={m.email} onChange={(e) => setM({ ...m, email: e.target.value })} /></Field>
          <Field label="Telefone"><input className={inputCls()} value={m.telefone || ""} onChange={(e) => setM({ ...m, telefone: maskPhone(e.target.value) })} /></Field>
          <Field label="Perfil de acesso" required>
            <Select value={m.perfil} onChange={(e) => setM({ ...m, perfil: e.target.value })}>
              {Object.entries(PERFIS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
            </Select>
          </Field>
          <p className="text-xs text-[#666666]">A senha de acesso será definida pelo back-end no primeiro login.</p>
        </Modal>
      )}
    </div>
  );
}

/* ---------- NOVO ATENDIMENTO (direto, sem solicitação) ---------- */
function NovoAtendimentoModal({ ctx, scope, dataInicial, onClose }) {
  const { alunos, orientadores, atendimentos, setAtendimentos, disponibilidades, reunioes, currentUserId, addToast } = ctx;
  const ativos = alunos;
  const hoje = dateKey(TODAY);
  const [f, setF] = useState({ alunoRm: ativos[0] ? ativos[0].rm : "", orientadorId: scope === "mine" ? currentUserId : (orientadores[0] || {}).id, data: dataInicial >= hoje ? dataInicial : hoje, horario: "", motivo: "", descricao: "" });
  const [err, setErr] = useState({});
  const foraDisp = f.horario && foraDisponibilidade(disponibilidades, { orientadorId: f.orientadorId, data: f.data, horario: f.horario });
  const diaComReuniao = reuniaoAtivaNoDia(reunioes, f.data);
  function save() {
    const e = {};
    if (!f.alunoRm) e.alunoRm = "Selecione um aluno.";
    if (!f.data) e.data = "Informe a data."; else if (f.data < hoje) e.data = "A data não pode ser no passado.";
    if (!f.horario) e.horario = "Informe o horário.";
    if (!f.motivo) e.motivo = "Informe o motivo do atendimento.";
    if (f.motivo === "Outro" && !f.descricao.trim()) e.descricao = "Descreva o motivo específico do atendimento.";
    if (f.data && reuniaoAtivaNoDia(reunioes, f.data)) e.data = "Existe uma reunião nesta data. Não é possível marcar atendimentos nesse dia.";
    if (f.data && f.horario) {
      const aluno = alunos.find((a) => a.rm === f.alunoRm);
      const responsaveisDoAluno = aluno ? ctx.respIdsDe(aluno.rm) : [];
      const conflito = conflitoDeCompromisso({ pessoaIds: [f.orientadorId, ...responsaveisDoAluno], data: f.data, inicio: toMin(f.horario), fim: toMin(f.horario) + DURACAO_ATENDIMENTO, atendimentos, reunioes });
      if (conflito) e.horario = conflito;
      if (atendimentos.some((a) => a.alunoRm === f.alunoRm && a.data === f.data && ATIVOS.includes(a.status) && intervalosSeSobrepoem(toMin(f.horario), toMin(f.horario)+DURACAO_ATENDIMENTO, toMin(a.horario), toMin(a.horario)+DURACAO_ATENDIMENTO))) e.horario = "Este aluno já possui um atendimento nesse intervalo.";
    }
    if (foraDisp) e.horario = "O horário escolhido está fora da disponibilidade cadastrada.";
    setErr(e);
    if (Object.keys(e).length) return;
    const aluno = alunos.find((a) => a.rm === f.alunoRm);
    setAtendimentos((p) => [...p, { id: uid("A"), alunoRm: f.alunoRm, orientadorId: f.orientadorId, responsavelId: ctx.respIdsDe(aluno.rm)[0] || "", responsaveisIds: ctx.respIdsDe(aluno.rm), data: f.data, horario: f.horario, motivo: f.motivo, descricao: f.descricao, observacoes: "", resultado: "", status: "Confirmado", origem: "direta", criadoEm: hoje }]);
    addToast("Atendimento agendado."); onClose();
  }
  return (
    <Modal title="Novo atendimento" onClose={onClose}
      footer={<><button className={btnS} onClick={onClose}>Cancelar</button><button className={btnP} onClick={save}>Agendar</button></>}>
      <p className="text-xs text-[#666666] mb-3">Agendamento direto, sem solicitação do responsável. Ele já entra como confirmado.</p>
      <Field label="Aluno" required error={err.alunoRm}>
        <Select busca value={f.alunoRm} onChange={(e) => setF({ ...f, alunoRm: e.target.value })} error={err.alunoRm}>{ativos.map((a) => <option key={a.rm} value={a.rm}>{a.nome} — {a.rm}</option>)}</Select>
      </Field>
      {scope !== "mine" && (
        <Field label="Orientador" required>
          <Select busca value={f.orientadorId} onChange={(e) => setF({ ...f, orientadorId: e.target.value })}>{orientadores.map((o) => <option key={o.id} value={o.id}>{o.nome}</option>)}</Select>
        </Field>
      )}
      <div className="grid grid-cols-2 gap-x-4">
        <Field label="Data" required error={err.data}><input type="date" min={hoje} className={inputCls(err.data)} value={f.data} onChange={(e) => setF({ ...f, data: e.target.value })} /></Field>
        <Field label="Horário" required error={err.horario}><input type="time" className={inputCls(err.horario)} value={f.horario} onChange={(e) => setF({ ...f, horario: e.target.value })} /></Field>
      </div>
      {diaComReuniao && <p role="alert" className="text-xs text-[#B20000] -mt-2 mb-3">Há uma reunião nesta data. O dia inteiro está bloqueado para atendimentos.</p>}
      {foraDisp && <p className="text-xs text-[#8A5A00] -mt-2 mb-3">Atenção: esse horário está fora da disponibilidade cadastrada do orientador.</p>}
      <Field label="Motivo" required error={err.motivo}>
        <Select value={f.motivo} onChange={(e) => setF({ ...f, motivo: e.target.value })} error={err.motivo}><option value="">Selecione...</option>{MOTIVOS.map((m) => <option key={m}>{m}</option>)}</Select>
      </Field>
      <Field label="Descrição" required={f.motivo === "Outro"} error={err.descricao}><TextArea error={err.descricao} value={f.descricao} onChange={(e) => setF({ ...f, descricao: e.target.value })} placeholder={f.motivo === "Outro" ? "Informe o motivo específico do atendimento" : "Detalhes do atendimento (opcional)"} /></Field>
    </Modal>
  );
}

/* ---------- SOLICITAÇÕES (pendentes / confirmados / recusadas) ---------- */
function SolicitacoesPage({ ctx, scope }) {
  const { atendimentos, setAtendimentos, alunos, orientadores, responsaveis, disponibilidades, reunioes, currentUserId, addToast, askConfirm } = ctx;
  const [tab, setTab] = useState("pendentes"), [q, setQ] = useState("");
  const base = scope === "mine" ? atendimentos.filter((a) => a.orientadorId === currentUserId) : atendimentos;
  const lists = { pendentes: base.filter((a) => a.status === "Pendente" && !foraDisponibilidade(disponibilidades, a)), confirmados: base.filter((a) => ATIVOS.includes(a.status)), recusadas: base.filter((a) => a.status === "Recusado") };
  const nome = (arr, id) => (arr.find((x) => x.id === id) || {}).nome || "—";
  const rows = lists[tab].filter((a) => !q || alunoNome(alunos, a.alunoRm).toLowerCase().includes(q.toLowerCase())).sort((a, b) => (a.data + a.horario > b.data + b.horario ? 1 : -1));
  const conflito = (a) => {
    const idsResponsaveis = ctx.respIdsDe(a.alunoRm);
    const conflitoPessoa = conflitoDeCompromisso({ pessoaIds: [a.orientadorId, ...idsResponsaveis], data: a.data, inicio: toMin(a.horario), fim: toMin(a.horario) + DURACAO_ATENDIMENTO, atendimentos, reunioes, ignorarAtendimento: a.id });
    const conflitoAluno = atendimentos.some(b => b.id !== a.id && b.alunoRm === a.alunoRm && b.data === a.data && ATIVOS.includes(b.status) && intervalosSeSobrepoem(toMin(a.horario), toMin(a.horario)+DURACAO_ATENDIMENTO, toMin(b.horario), toMin(b.horario)+DURACAO_ATENDIMENTO));
    return conflitoPessoa || (conflitoAluno ? "O aluno já possui outro atendimento neste intervalo." : "");
  };
  const setStatus = (a, status) => setAtendimentos((p) => p.map((x) => (x.id === a.id ? { ...x, status } : x)));

  function aprovar(a) {
    if (reuniaoAtivaNoDia(reunioes, a.data)) return addToast("Há uma reunião nesta data. O dia inteiro está bloqueado para atendimentos.", "error");
    if (foraDisponibilidade(disponibilidades, a)) return addToast("O horário solicitado está fora da disponibilidade cadastrada.", "error");
    if (conflito(a)) return addToast(typeof conflito(a) === "string" ? conflito(a) : "Conflito de horário.", "error");
    setStatus(a, "Confirmado"); addToast("Solicitação aprovada.");
  }
  function recusar(a) {
    askConfirm({ title: "Recusar solicitação", message: `Recusar a solicitação de ${alunoNome(alunos, a.alunoRm)} em ${formatDate(a.data)}?`, danger: true, confirmLabel: "Recusar solicitação",
      onConfirm: () => { setStatus(a, "Recusado"); addToast("Solicitação recusada."); } });
  }
  const cols = [
    { key: "resp", label: "Responsáveis", render: (a) => ctx.nomesRespDe(a.alunoRm) },
    { key: "aluno", label: "Aluno", render: (a) => alunoNome(alunos, a.alunoRm) },
    { key: "orient", label: "Orientador", render: (a) => nome(orientadores, a.orientadorId) },
    { key: "data", label: "Data", render: (a) => formatDate(a.data) },
    { key: "horario", label: "Horário" },
    { key: "status", label: "Status", render: (a) => (<div className="flex items-center gap-2"><Badge status={a.status} />{tab === "pendentes" && foraDisponibilidade(disponibilidades, a) && <span className="text-xs text-[#8A5A00]">Fora da disponibilidade</span>}{tab === "pendentes" && conflito(a) && <span className="text-xs text-[#B20000]">{conflito(a)}</span>}</div>) },
    ...(tab === "pendentes" ? [{ key: "acoes", label: "Ações", render: (a) => (
      <div className="flex gap-2">
        <button onClick={() => aprovar(a)} className="px-3 py-1.5 rounded-lg text-xs font-medium bg-[#A0C340] hover:bg-[#8FB033] text-[#1F2A05] flex items-center gap-1"><Check size={13} /> Aprovar</button>
        <button onClick={() => recusar(a)} className="px-3 py-1.5 rounded-lg text-xs font-medium border border-[#FF4C4D]/30 text-[#B20000] hover:bg-[#FF4C4D]/10 flex items-center gap-1"><X size={13} /> Recusar</button>
      </div>) }] : []),
  ];
  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-2">
        {[["pendentes", "Pendentes"], ["confirmados", "Agendamentos confirmados"], ["recusadas", "Recusadas"]].map(([k, l]) => (
          <button key={k} aria-pressed={tab === k} onClick={() => setTab(k)} className={`px-3 py-2 rounded-lg text-sm border ${tab === k ? "bg-[#B20000] text-white border-[#B20000]" : "border-[#DADADA] text-gray-700 hover:bg-[#E6E6E6]"}`}>{l} ({lists[k].length})</button>
        ))}
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Buscar aluno" aria-label="Buscar aluno" className={inputCls() + " max-w-[13.75rem] ml-auto"} />
      </div>
      <DataTable columns={cols} rows={rows} emptyTitle="Nada por aqui" emptyMessage="Nenhum registro nesta lista." />
    </div>
  );
}

/* ---------- DISPONIBILIDADE DOS ORIENTADORES ---------- */
function DisponibilidadePage({ ctx, scope }) {
  const { disponibilidades, setDisponibilidades, orientadores, currentUserId, addToast, askConfirm } = ctx;
  const [oid, setOid] = useState(scope === "mine" ? currentUserId : orientadores[0]?.id);
  const [m, setM] = useState(null), [err, setErr] = useState("");
  const mine = disponibilidades.filter((d) => d.orientadorId === oid).sort((a, b) => a.inicio.localeCompare(b.inicio));
  function save() {
    if (!m.inicio || !m.fim) return setErr("Informe o início e o fim.");
    const ini = toMin(m.inicio), fim = toMin(m.fim);
    if (fim <= ini) return setErr("O horário final deve ser depois do inicial.");
    if (fim - ini < DURACAO_ATENDIMENTO) return setErr(`O período precisa ter ao menos ${DURACAO_ATENDIMENTO} minutos (duração de um atendimento).`);
    const conf = disponibilidades.find((d) => d.id !== m.id && d.orientadorId === oid && d.dia === Number(m.dia) && ini < toMin(d.fim) && toMin(d.inicio) < fim);
    if (conf) return setErr(`Conflito com a disponibilidade de ${conf.inicio} às ${conf.fim} nesse dia.`);
    // intervalos (almoço, pausas): até MAX_INTERVALOS, dentro do período e sem sobreposição entre si
    const ints = m.intervalos || [];
    if (ints.length > MAX_INTERVALOS) return setErr(`Use no máximo ${MAX_INTERVALOS} intervalos.`);
    for (let k = 0; k < ints.length; k++) {
      const i = ints[k];
      if (!i.inicio || !i.fim) return setErr(`Intervalo ${k + 1}: informe o início e o fim (ou remova o intervalo).`);
      if (toMin(i.fim) <= toMin(i.inicio)) return setErr(`Intervalo ${k + 1}: o horário final deve ser depois do inicial.`);
      if (toMin(i.inicio) < ini || toMin(i.fim) > fim) return setErr(`Intervalo ${k + 1}: precisa ficar dentro do período (${m.inicio} às ${m.fim}).`);
    }
    const ord = [...ints].sort((x, y) => toMin(x.inicio) - toMin(y.inicio));
    for (let k = 1; k < ord.length; k++) {
      if (toMin(ord[k].inicio) < toMin(ord[k - 1].fim)) return setErr(`Os intervalos ${ord[k - 1].inicio}–${ord[k - 1].fim} e ${ord[k].inicio}–${ord[k].fim} se sobrepõem. Ajuste os horários.`);
    }
    // TODO(API): POST/PUT API_ROTAS.disponibilidades com { dia, inicio, fim, intervalos }
    const item = { id: m.id || uid("D"), orientadorId: oid, dia: Number(m.dia), inicio: m.inicio, fim: m.fim, intervalos: ord.map((i) => ({ inicio: i.inicio, fim: i.fim })) };
    setDisponibilidades((p) => (m.id ? p.map((x) => (x.id === m.id ? item : x)) : [...p, item]));
    addToast(m.id ? "Disponibilidade atualizada." : "Disponibilidade adicionada."); setM(null);
  }
  function remover(d) {
    askConfirm({ title: "Excluir disponibilidade", message: `Excluir ${DIAS[d.dia]}, ${d.inicio} às ${d.fim}?`, danger: true, confirmLabel: "Excluir", onConfirm: () => { setDisponibilidades((p) => p.filter((x) => x.id !== d.id)); addToast("Disponibilidade excluída."); } });
  }
  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-3">
        {scope !== "mine" && (
          <Select busca value={oid} onChange={(e) => setOid(e.target.value)} aria-label="Orientador" style={{ maxWidth: "17.5rem" }}>{orientadores.map((o) => <option key={o.id} value={o.id}>{o.nome}</option>)}</Select>
        )}
        <button className={btnP + " ml-auto"} onClick={() => { setErr(""); setM({ dia: 1, inicio: "08:00", fim: "12:00", intervalos: [] }); }}><Plus size={16} /> Adicionar horário</button>
      </div>
      <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {[1, 2, 3, 4, 5, 6, 0].map((dia) => (
          <div key={dia} className="bg-white rounded-xl border border-[#E6E6E6] shadow-sm p-4">
            <p className="font-medium text-gray-800 mb-2">{DIAS[dia]}</p>
            {mine.filter((d) => d.dia === dia).map((d) => (
              <div key={d.id} className="rounded-lg bg-[#F8F8F8] border border-[#E6E6E6] px-3 py-2 mb-2 text-sm">
                <div className="flex items-center justify-between">
                <span className="flex items-center gap-1.5"><Clock size={14} /> {d.inicio} – {d.fim}</span>
                <span className="flex"><IconBtn icon={Pencil} title="Editar" onClick={() => { setErr(""); setM({ ...d, intervalos: (d.intervalos || []).map((i) => ({ ...i })) }); }} /><IconBtn icon={Trash2} title="Excluir" tone="danger" onClick={() => remover(d)} /></span>
                </div>
                {(d.intervalos || []).length > 0 && <p className="text-xs text-[#666666] mt-1">Intervalos: {d.intervalos.map((i) => `${i.inicio}–${i.fim}`).join(" · ")}</p>}
              </div>
            ))}
            {!mine.some((d) => d.dia === dia) && <p className="text-xs text-[#666666]">Sem horários</p>}
          </div>
        ))}
      </div>
      <p className="text-xs text-[#666666]">O responsável só consegue escolher horários dentro destes períodos, fora dos intervalos e sem choque com outros atendimentos.</p>
      {m && (
        <Modal title={m.id ? "Editar disponibilidade" : "Nova disponibilidade"} onClose={() => setM(null)} size="sm"
          footer={<><button className={btnS} onClick={() => setM(null)}>Cancelar</button><button className={btnP} onClick={save}>Salvar</button></>}>
          <Field label="Dia da semana"><Select value={m.dia} onChange={(e) => setM({ ...m, dia: e.target.value })}>{DIAS.map((d, i) => <option key={d} value={i}>{d}</option>)}</Select></Field>
          <div className="grid grid-cols-2 gap-x-4">
            <Field label="Início"><input type="time" step="60" className={inputCls()} value={m.inicio} onChange={(e) => setM({ ...m, inicio: e.target.value })} /></Field>
            <Field label="Fim"><input type="time" step="60" className={inputCls()} value={m.fim} onChange={(e) => setM({ ...m, fim: e.target.value })} /></Field>
          </div>
          <div className="mb-2">
            <div className="flex items-center justify-between mb-2">
              <p className="text-sm font-medium text-gray-700">Intervalos <span className="text-xs font-normal text-[#666666]">(almoço, pausas — até {MAX_INTERVALOS})</span></p>
              <button type="button" disabled={(m.intervalos || []).length >= MAX_INTERVALOS}
                onClick={() => setM({ ...m, intervalos: [...(m.intervalos || []), { inicio: "", fim: "" }] })}
                className="text-xs font-medium text-[#B20000] hover:underline disabled:opacity-40 disabled:no-underline">+ Adicionar intervalo</button>
            </div>
            {(m.intervalos || []).length === 0 && <p className="text-xs text-[#666666]">Nenhum intervalo: todo o período fica disponível para atendimento.</p>}
            {(m.intervalos || []).map((i, k) => (
              <div key={k} className="flex items-end gap-2 mb-2">
                <label className="flex-1 text-xs text-[#666666]">Início
                  <input type="time" step="60" className={inputCls()} value={i.inicio} onChange={(e) => setM({ ...m, intervalos: m.intervalos.map((x, y) => (y === k ? { ...x, inicio: e.target.value } : x)) })} /></label>
                <label className="flex-1 text-xs text-[#666666]">Fim
                  <input type="time" step="60" className={inputCls()} value={i.fim} onChange={(e) => setM({ ...m, intervalos: m.intervalos.map((x, y) => (y === k ? { ...x, fim: e.target.value } : x)) })} /></label>
                <button type="button" aria-label={`Remover intervalo ${k + 1}`} onClick={() => setM({ ...m, intervalos: m.intervalos.filter((_, y) => y !== k) })}
                  className="p-2.5 rounded-lg text-[#B20000] hover:bg-[#B20000]/10"><Trash2 size={16} /></button>
              </div>
            ))}
          </div>
          {err && <p role="alert" className="text-sm text-[#B20000]">{err}</p>}
        </Modal>
      )}
    </div>
  );
}

/* ---------- REUNIÕES ---------- */
function HistoricoInstituicaoPage({ ctx }) {
  const { atendimentos, reunioes, alunos, orientadores, responsaveis, admins } = ctx;
  const [tipo, setTipo] = useState("todos");
  const [detalhe, setDetalhe] = useState(null);
  const pessoas = [...(admins || []), ...orientadores, ...responsaveis];
  const registros = [
    ...atendimentos.filter(a => a.status !== "Pendente" && a.status !== "Recusado").map(a => ({ tipo:"Atendimento", id:a.id, data:a.data, inicio:a.horario, fim:fimAtendimento(a), titulo:alunoNome(alunos,a.alunoRm), motivo:a.motivo || "", participantes:[orientadorNome(orientadores,a.orientadorId), ctx.nomesRespDe(a.alunoRm)], descricao:a.descricao || a.resultado || "", status:a.status })),
    ...reunioes.filter(r => r.status === "Cancelada" || r.data < dateKey(TODAY) || (r.data === dateKey(TODAY) && toMin(r.horarioFim || r.horario) <= toMin(new Date().toTimeString().slice(0,5)))).map(r => ({ tipo:"Reunião", id:r.id, data:r.data, inicio:r.horario, fim:r.horarioFim || r.horario, titulo:r.assunto, motivo:r.assunto || "Reunião", participantes:(r.participantes || []).map(id => (pessoas.find(p=>p.id===id)||{nome:id}).nome), descricao:r.descricao || "", status:r.status === "Cancelada" ? "Cancelada" : "Realizada" }))
  ].filter(r => tipo === "todos" || (tipo === "reuniao" ? r.tipo === "Reunião" : r.tipo === "Atendimento")).sort((a,b)=>(b.data+b.inicio).localeCompare(a.data+a.inicio));
  return <div className="space-y-4">
    <div className="flex flex-wrap gap-2"><button className={tipo==="todos"?btnP:btnS} onClick={()=>setTipo("todos")}>Todos</button><button className={tipo==="atendimento"?btnP:btnS} onClick={()=>setTipo("atendimento")}>Atendimentos</button><button className={tipo==="reuniao"?btnP:btnS} onClick={()=>setTipo("reuniao")}>Reuniões</button></div>
    <DataTable columns={[
      {key:"tipo",label:"Tipo",render:r=><span className={`inline-flex px-2 py-1 rounded-full text-xs font-semibold ${r.tipo==="Reunião"?"bg-blue-50 text-blue-700":"bg-red-50 text-[#7E0000]"}`}>{r.tipo}</span>},
      {key:"titulo",label:"Registro",render:r=>r.titulo},
      {key:"data",label:"Data e horário",render:r=>`${formatDate(r.data)} · ${r.inicio}–${r.fim}`},
      {key:"status",label:"Status",render:r=>r.tipo === "Atendimento" ? <Badge status={r.status}/> : <span className="text-xs text-gray-600">{r.status}</span>},
      {key:"participantes",label:"Participantes",render:r=><span className="whitespace-normal break-words">{r.participantes.filter(Boolean).join(", ")}</span>},
      {key:"motivo",label:"Motivo",render:r=><button className="px-3 py-1.5 rounded-lg border border-[#DADADA] text-xs hover:bg-[#F8F8F8]" onClick={()=>setDetalhe(r)}>Ver motivo</button>}
    ]} rows={registros} emptyTitle="Nenhum registro no histórico" emptyMessage="Atendimentos finalizados e reuniões realizadas aparecerão aqui."/>
    {detalhe && <Modal title={detalhe.tipo === "Reunião" ? "Detalhes da reunião" : "Motivo do atendimento"} onClose={()=>setDetalhe(null)} size="md" footer={<button className={btnP} onClick={()=>setDetalhe(null)}>Fechar</button>}>
      <div className="space-y-3"><p className="text-sm text-gray-700"><strong>Registro:</strong> {detalhe.titulo}</p><p className="text-sm text-gray-700"><strong>Data e horário:</strong> {formatDate(detalhe.data)} · {detalhe.inicio}–{detalhe.fim}</p><p className="text-sm text-gray-700"><strong>Participantes:</strong> {detalhe.participantes.filter(Boolean).join(", ") || "—"}</p><div><p className="text-sm font-semibold text-gray-800 mb-1">Motivo</p><p className="text-sm text-gray-700 whitespace-pre-wrap break-words">{detalhe.motivo || "Não informado."}</p></div>{detalhe.descricao && <div><p className="text-sm font-semibold text-gray-800 mb-1">Descrição / observações</p><p className="text-sm text-gray-700 whitespace-pre-wrap break-words">{detalhe.descricao}</p></div>}</div>
    </Modal>}
  </div>;
}

function ReunioesPage({ ctx }) {
  const { reunioes, setReunioes, atendimentos, orientadores, responsaveis, admins, alunos, currentUserId, role, addToast, askConfirm } = ctx;
  const [tab, setTab] = useState("proximas"), [m, setM] = useState(null), [view, setView] = useState(null), [err, setErr] = useState({});
  const [bp, setBp] = useState(""), [fp, setFp] = useState("");
  const pessoas = [...alunos.map((x) => ({ ...x, id: x.rm, nome: x.nome, tipo: "Aluno" })), ...admins.map((x) => ({ ...x, tipo: "Administrador" })), ...orientadores.map((x) => ({ ...x, tipo: "Orientador" })), ...responsaveis.map((x) => ({ ...x, tipo: "Responsável" }))];
  const nomeDe = (id) => (pessoas.find((p) => p.id === id) || { nome: id }).nome;
  const hoje = dateKey(TODAY);
  useEffect(() => {
    const abrirNovaReuniao = () => { setErr({}); setBp(""); setFp(""); setM({ assunto:"", descricao:"", data:hoje, horario:"", horarioFim:"", participantes:[] }); };
    window.addEventListener("sigep:nova-reuniao", abrirNovaReuniao);
    if (sessionStorage.getItem("sigepAbrirNovaReuniao") === "1") { sessionStorage.removeItem("sigepAbrirNovaReuniao"); abrirNovaReuniao(); }
    return () => window.removeEventListener("sigep:nova-reuniao", abrirNovaReuniao);
  }, [hoje]);
  const situacao = (r) => (r.status === "Cancelada" ? "Cancelado" : (r.data < hoje || (r.data === hoje && toMin(r.horarioFim || r.horario) <= toMin(new Date().toTimeString().slice(0,5))) ? "Concluído" : "Agendado"));
  const visiveis = reunioes.filter((r) => role === "instituicao" || r.criadoPor === currentUserId || r.participantes.includes(currentUserId));
  const rows = visiveis.filter((r) => (tab === "proximas" ? situacao(r) === "Agendado" : true)).sort((a, b) => (a.data + a.horario).localeCompare(b.data + b.horario));
  const participantesPermitidos = (p) => role !== "orientador" || p.tipo === "Aluno";
  function save() {
    const e = {};
    if (!m.assunto.trim()) e.assunto = "Informe o assunto.";
    if (!m.data) e.data = "Informe a data."; else if (!m.id && m.data < hoje) e.data = "A data não pode ser no passado.";
    if (!m.horario) e.horario = "Informe o horário de início.";
    if (!m.horarioFim) e.horarioFim = "Informe o horário de término.";
    if (m.horario && m.horarioFim && toMin(m.horarioFim) <= toMin(m.horario)) e.horarioFim = "O término deve ser depois do início.";
    if (!m.participantes.length) e.part = "Selecione ao menos um participante.";
    if (m.participantes.some((id) => { const p = pessoas.find((x) => x.id === id); return !p || !participantesPermitidos(p); })) e.part = "Orientadores podem adicionar somente alunos. Outros perfis são permitidos apenas à Instituição.";
    if (m.data && (!m.id || (m.id && reunioes.find(r => r.id === m.id)?.data !== m.data)) && atendimentos.some(a => a.data === m.data && ATIVOS.includes(a.status))) e.data = "Já existem atendimentos nesta data. Remaneje ou cancele esses atendimentos antes de cadastrar a reunião.";
    if (m.data && m.horario && m.horarioFim && toMin(m.horarioFim) > toMin(m.horario)) {
      const ids = [...new Set([currentUserId, ...m.participantes])];
      const conflito = conflitoDeCompromisso({ pessoaIds: ids, data: m.data, inicio: toMin(m.horario), fim: toMin(m.horarioFim), atendimentos, reunioes, ignorarReuniao: m.id || null });
      if (conflito) e.horario = conflito;
    }
    setErr(e); if (Object.keys(e).length) return;
    const item = { ...m, id: m.id || uid("M"), assunto: m.assunto.trim(), horarioFim: m.horarioFim, status: "Agendada", criadoPor: m.criadoPor || currentUserId };
    setReunioes((p) => (m.id ? p.map((x) => (x.id === m.id ? item : x)) : [...p, item]));
    addToast(m.id ? "Reunião atualizada." : "Reunião cadastrada. O dia ficará indisponível para atendimentos."); setM(null);
  }
  function cancelar(r) {
    askConfirm({ title: "Cancelar reunião", message: `Cancelar "${r.assunto}"?`, danger: true, confirmLabel: "Cancelar reunião",
      onConfirm: () => { setReunioes((p) => p.map((x) => (x.id === r.id ? { ...x, status: "Cancelada" } : x))); addToast("Reunião cancelada. A data voltou a ficar disponível para atendimentos."); } });
  }
  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-2">
        {[ ["proximas", "Próximas"], ["historico", "Histórico"] ].map(([k,l]) => <button key={k} aria-pressed={tab===k} onClick={() => setTab(k)} className={`px-3 py-2 rounded-lg text-sm border ${tab===k ? "bg-[#B20000] text-white border-[#B20000]" : "border-[#DADADA] text-gray-700 hover:bg-[#E6E6E6]"}`}>{l}</button>)}
      </div>
      <DataTable columns={[
        {key:"assunto",label:"Assunto"}, {key:"data",label:"Data e horário",render:r=>`${formatDate(r.data)} · ${r.horario}–${r.horarioFim || r.horario}`},
        {key:"p",label:"Participantes",render:r=>r.participantes.length}, {key:"s",label:"Status",render:r=><Badge status={situacao(r)}/>},
        {key:"acoes",label:"Ações",render:r=><div className="flex gap-0.5"><IconBtn icon={Eye} title="Consultar" onClick={()=>setView(r)}/>{situacao(r)==="Agendado" && (role === "instituicao" || r.criadoPor === currentUserId) && <><IconBtn icon={Pencil} title="Editar" onClick={()=>{setErr({});setBp("");setFp("");setM({...r});}}/><IconBtn icon={Ban} title="Cancelar" tone="danger" onClick={()=>cancelar(r)}/></>}</div>}
      ]} rows={rows} emptyTitle="Nenhuma reunião" emptyMessage="Cadastre uma nova reunião para começar."/>
      {view && <Modal title={view.assunto} onClose={()=>setView(null)} size="sm" footer={<button className={btnS} onClick={()=>setView(null)}>Fechar</button>}>
        <p className="text-sm text-gray-700 mb-1"><Badge status={situacao(view)}/> &nbsp;{formatDate(view.data)} · {view.horario}–{view.horarioFim || view.horario}</p>
        {view.descricao && <p className="text-sm text-[#666666] mb-3">{view.descricao}</p>}
        <p className="text-sm font-medium text-gray-800 mb-1">Participantes</p><ul className="text-sm text-gray-700 space-y-1">{view.participantes.map(id=><li key={id}>{nomeDe(id)}</li>)}</ul>
      </Modal>}
      {m && <Modal title={m.id?"Editar reunião":"Nova reunião"} onClose={()=>setM(null)} footer={<><button className={btnS} onClick={()=>setM(null)}>Cancelar</button><button className={btnP} onClick={save}>Salvar</button></>}>
        <Field label="Assunto" required error={err.assunto}><input className={inputCls(err.assunto)} value={m.assunto} onChange={e=>setM({...m,assunto:e.target.value})}/></Field>
        <div className="grid grid-cols-2 gap-x-4"><Field label="Data" required error={err.data}><input type="date" min={hoje} className={inputCls(err.data)} value={m.data} onChange={e=>setM({...m,data:e.target.value})}/></Field>
        <Field label="Início" required error={err.horario}><input type="time" step="60" className={inputCls(err.horario)} value={m.horario} onChange={e=>setM({...m,horario:e.target.value})}/></Field>
        <Field label="Término" required error={err.horarioFim}><input type="time" step="60" className={inputCls(err.horarioFim)} value={m.horarioFim} onChange={e=>setM({...m,horarioFim:e.target.value})}/></Field></div>
        <Field label="Descrição"><TextArea value={m.descricao || ""} onChange={e=>setM({...m,descricao:e.target.value})}/></Field>
        <Field label={`Participantes (${m.participantes.length} selecionado${m.participantes.length===1?"":"s"})`} required error={err.part}>
          {(() => { const lista=pessoas.filter(p=>participantesPermitidos(p)&&(!fp||p.tipo===fp)&&(!bp||p.nome.toLowerCase().includes(bp.toLowerCase()))); const todos=lista.length>0&&lista.every(p=>m.participantes.includes(p.id)); const alternar=id=>setM({...m,participantes:m.participantes.includes(id)?m.participantes.filter(x=>x!==id):[...m.participantes,id]});
            return <><div className="flex flex-wrap gap-2 mb-2"><input value={bp} onChange={e=>setBp(e.target.value)} placeholder="Pesquisar pelo nome" className={inputCls()+" flex-1 min-w-[10rem]"}/><Select value={fp} onChange={e=>setFp(e.target.value)} aria-label="Filtrar por perfil"><option value="">Todos os perfis</option><option>Administrador</option><option>Orientador</option><option>Responsável</option><option>Aluno</option></Select></div>
              {role==="orientador" && <p className="text-xs text-[#666666] mb-2">Como orientador, você pode adicionar somente alunos. A Instituição pode adicionar todos os perfis.</p>}
              <div className="flex gap-3 mb-2 text-xs"><button type="button" disabled={!lista.length} onClick={()=>setM({...m,participantes:todos?m.participantes.filter(id=>!lista.some(p=>p.id===id)):[...new Set([...m.participantes,...lista.map(p=>p.id)])]})} className="text-[#B20000] hover:underline">{todos?"Desmarcar resultados":`Selecionar resultados (${lista.length})`}</button><button type="button" onClick={()=>setM({...m,participantes:[]})} className="text-[#666666] hover:underline">Limpar seleção</button></div>
              <div className="max-h-44 overflow-y-auto border border-[#DADADA] rounded-lg divide-y divide-[#E6E6E6]">{lista.map(p=><label key={p.id} className="flex items-center gap-2 px-3 py-2 text-sm cursor-pointer hover:bg-[#F8F8F8]"><input type="checkbox" checked={m.participantes.includes(p.id)} onChange={()=>alternar(p.id)} className="accent-[#B20000]"/>{p.nome}<span className="text-xs text-[#666666]">· {p.tipo}</span></label>)}{!lista.length&&<p className="px-3 py-3 text-sm text-[#666666]">Ninguém encontrado.</p>}</div>
            </>;
          })()}
        </Field>
        {err.horario && <p role="alert" className="text-sm text-[#B20000]">{err.horario}</p>}
      </Modal>}
    </div>
  );
}

/* ---------- AUDITORIA ---------- */
function AuditoriaPage({ ctx }) {
  const { auditoria } = ctx;
  const [f, setF] = useState({ usuario: "", cat: "", de: "", ate: "" });
  const usuarios = [...new Set(auditoria.map((a) => a.usuario))], cats = [...new Set(auditoria.map((a) => a.cat))];
  const rows = auditoria.filter((a) => (!f.usuario || a.usuario === f.usuario) && (!f.cat || a.cat === f.cat) && (!f.de || a.quando.slice(0, 10) >= f.de) && (!f.ate || a.quando.slice(0, 10) <= f.ate))
    .sort((a, b) => (a.quando < b.quando ? 1 : -1));
  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-end gap-3">
        <Select busca value={f.usuario} onChange={(e) => setF({ ...f, usuario: e.target.value })} aria-label="Usuário" style={{ maxWidth: "13.75rem" }}><option value="">Todos os usuários</option>{usuarios.map((u) => <option key={u}>{u}</option>)}</Select>
        <Select value={f.cat} onChange={(e) => setF({ ...f, cat: e.target.value })} aria-label="Tipo de ação" style={{ maxWidth: "12.5rem" }}><option value="">Todos os tipos</option>{cats.map((c) => <option key={c}>{c}</option>)}</Select>
        <label className="text-xs text-[#666666]">De<input type="date" value={f.de} onChange={(e) => setF({ ...f, de: e.target.value })} className={inputCls() + " block"} /></label>
        <label className="text-xs text-[#666666]">Até<input type="date" value={f.ate} onChange={(e) => setF({ ...f, ate: e.target.value })} className={inputCls() + " block"} /></label>
        <button className={btnS} onClick={() => setF({ usuario: "", cat: "", de: "", ate: "" })}>Limpar filtros</button>
      </div>
      <DataTable
        columns={[
          { key: "quando", label: "Data e horário", render: (a) => fmtDT(a.quando) },
          { key: "usuario", label: "Usuário", render: (a) => `${a.usuario} (${a.perfil})` },
          { key: "cat", label: "Tipo" }, { key: "acao", label: "Ação" },
        ]}
        rows={rows} emptyTitle="Nenhuma atividade encontrada" emptyMessage="Ajuste os filtros para ver outros registros."
      />
    </div>
  );
}

/* ---------- NOTIFICAÇÕES (todos os perfis) ---------- */
function NotificacoesPage({ ctx }) {
  const { notificacoes, setNotificacoes, currentUserId, addToast } = ctx;
  const [cat, setCat] = useState(""), [soNaoLidas, setSo] = useState(false);
  const catDe = (n) => n.cat || "Agendamentos";
  const mine = notificacoes.filter((n) => n.responsavelId === currentUserId).sort((a, b) => (a.data < b.data ? 1 : a.data > b.data ? -1 : 0));
  const cats = [...new Set(mine.map(catDe))];
  const rows = mine.filter((n) => (!cat || catDe(n) === cat) && (!soNaoLidas || !n.lida));
  const dias = [...new Set(rows.map((n) => n.data))];
  const marcar = (id, lida) => setNotificacoes((p) => p.map((n) => (n.id === id ? { ...n, lida } : n)));
  if (mine.length === 0) return <EmptyState icon={Bell} title="Nenhuma notificação" message="Você será avisado aqui sobre solicitações, aprovações, recusas e alterações." />;
  return (
    <div className="max-w-2xl space-y-4">
      <div className="flex flex-wrap items-center gap-2">
        {["", ...cats].map((c) => (
          <button key={c || "todas"} aria-pressed={cat === c} onClick={() => setCat(c)} className={`px-3 py-1.5 rounded-full text-xs border ${cat === c ? "bg-[#B20000] text-white border-[#B20000]" : "border-[#DADADA] text-gray-700 hover:bg-[#E6E6E6]"}`}>{c || "Todas"}</button>
        ))}
        <label className="flex items-center gap-1.5 text-xs text-[#666666] ml-auto"><input type="checkbox" checked={soNaoLidas} onChange={(e) => setSo(e.target.checked)} className="accent-[#B20000]" /> Só não lidas</label>
        <button onClick={() => { setNotificacoes((p) => p.map((n) => (n.responsavelId === currentUserId ? { ...n, lida: true } : n))); addToast("Todas as notificações foram marcadas como lidas."); }} className="text-xs font-medium text-[#B20000] hover:underline">Marcar todas como lidas</button>
      </div>
      {dias.map((d) => (
        <div key={d} className="space-y-2">
          <p className="text-xs font-medium uppercase tracking-wide text-[#666666]">{formatDate(d)}</p>
          {rows.filter((n) => n.data === d).map((n) => (
            <div key={n.id} className={`flex items-start gap-3 p-4 rounded-xl border ${n.lida ? "bg-white border-[#E6E6E6]" : "bg-[#B20000]/5 border-[#B20000]/20"}`}>
              <div className={`w-9 h-9 rounded-full flex items-center justify-center shrink-0 ${n.lida ? "bg-[#E6E6E6] text-gray-400" : "bg-[#B20000] text-white"}`}><Bell size={15} /></div>
              <div className="flex-1 min-w-0">
                <p className={`text-sm ${n.lida ? "text-[#666666]" : "text-gray-800 font-medium"}`}>{n.texto}</p>
                <p className="text-xs text-gray-400 mt-0.5">{catDe(n)}</p>
              </div>
              <button onClick={() => marcar(n.id, !n.lida)} className="text-xs text-[#B20000] hover:underline shrink-0">{n.lida ? "Marcar como não lida" : "Marcar como lida"}</button>
            </div>
          ))}
        </div>
      ))}
      {rows.length === 0 && <p className="text-sm text-[#666666]">Nenhuma notificação com esses filtros.</p>}
    </div>
  );
}


const __root = ReactDOM.createRoot(document.getElementById("root"));
__root.render(<SigepApp />);

</script>

<script type="module">
  import React from "react";
  import ReactDOM from "react-dom/client";
  import * as ReactDOMFull from "react-dom";
  import * as LucideReact from "lucide-react";
  import * as Recharts from "recharts";

  window.React = React;
  window.ReactDOM = ReactDOM;
  // createPortal vem do pacote "react-dom" (o "react-dom/client" só tem createRoot). Se faltar, o app usa um plano B sem portal.
  window.__createPortal = ReactDOMFull.createPortal || (ReactDOMFull.default && ReactDOMFull.default.createPortal) || null;
  window.__Lucide = LucideReact;
  window.__Recharts = Recharts;

  const src = document.getElementById("app-src").textContent;
  const transformed = Babel.transform(src, {
    presets: [["react", { runtime: "classic" }]]
  }).code;
  const script = document.createElement("script");
  script.textContent = transformed;
  document.body.appendChild(script);
</script>
</body>
</html>
